#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';
const SQL_FILE_PATTERN = /\.sql$/i;

/**
 * Main function to run migrations
 */
async function runMigrations() {
    console.log('📊 Database Migration Script');
    console.log('===============================\n');

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`❌ Error: Migrations directory "${MIGRATIONS_DIR}" not found.`);
            console.log('Please create a "migrations" directory in the current folder.');
            process.exit(1);
        }

        // Read all files from migrations directory
        const allFiles = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = allFiles.filter(file => SQL_FILE_PATTERN.test(file));

        if (sqlFiles.length === 0) {
            console.log('📭 No SQL migration files found in the migrations directory.');
            console.log('Expected files with .sql extension (e.g., 001_create_table.sql)');
            return;
        }

        console.log(`📁 Found ${sqlFiles.length} SQL migration file(s) in "${MIGRATIONS_DIR}":\n`);

        // Sort files numerically/alphabetically to ensure proper order
        const sortedFiles = sqlFiles.sort((a, b) => {
            // Extract numbers from filenames for numerical sorting
            const numA = extractPrefixNumber(a);
            const numB = extractPrefixNumber(b);

            if (numA !== null && numB !== null) {
                return numA - numB;
            }

            // Fallback to alphabetical sorting if no numbers found
            return a.localeCompare(b);
        });

        // Log each migration file in order
        console.log('📋 Migration files to apply (in order):');
        console.log('---------------------------------------');

        sortedFiles.forEach((file, index) => {
            const filePath = path.join(MIGRATIONS_DIR, file);
            const fileSize = fs.statSync(filePath).size;

            // Read first line as description (if it's a comment)
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLine = content.split('\n')[0].trim();
            const description = firstLine.startsWith('--') 
                ? firstLine.substring(2).trim() 
                : 'No description provided';

            console.log(`${index + 1}. ${file} (${formatFileSize(fileSize)})`);
            console.log(`   📄 ${description}`);
            console.log(`   📍 ${filePath}\n`);
        });

        console.log('✅ Migration plan ready. The above files would be executed in this order.');
        console.log('\n💡 To actually execute these migrations, you would:');
        console.log('1. Connect to your database');
        console.log('2. Read each SQL file content');
        console.log('3. Execute the SQL statements');
        console.log('4. Track which migrations have been applied');

    } catch (error) {
        console.error(`❌ Error running migrations: ${error.message}`);
        process.exit(1);
    }
}

/**
 * Extract numeric prefix from filename
 * @param {string} filename 
 * @returns {number|null} Numeric prefix or null if not found
 */
function extractPrefixNumber(filename) {
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : null;
}

/**
 * Format file size in human-readable format
 * @param {number} bytes 
 * @returns {string} Formatted file size
 */
function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';

    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

// Run the migrations if this script is executed directly
if (require.main === module) {
    runMigrations().catch(error => {
        console.error('Unhandled error:', error);
        process.exit(1);
    });
}

module.exports = { runMigrations };

// Test file to demonstrate using migrate.js as a module
const { runMigrations } = require('./migrate.js');

console.log('Testing migrate.js as a module...\n');
runMigrations().then(() => {
    console.log('\n✅ Module test completed successfully');
}).catch(error => {
    console.error('❌ Module test failed:', error);
});

