#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 * 
 * Usage: node migrate.js
 */

function getMigrationFiles(migrationsDir) {
    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files by name (assuming prefix numbers like 001_, 002_, etc.)
    sqlFiles.sort((a, b) => {
        // Extract numeric prefixes if they exist
        const numA = parseInt(a.split('_')[0]) || 0;
        const numB = parseInt(b.split('_')[0]) || 0;
        return numA - numB;
    });

    return sqlFiles;
}

function readMigrationFile(migrationsDir, filename) {
    const filePath = path.join(migrationsDir, filename);
    return fs.readFileSync(filePath, 'utf8');
}

function main() {
    const migrationsDir = './migrations';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory '${migrationsDir}' not found.`);
        process.exit(1);
    }

    console.log('Starting migration process...');
    console.log('Reading migration files from:', migrationsDir);
    console.log('---');

    // Get all migration files in order
    const migrationFiles = getMigrationFiles(migrationsDir);

    if (migrationFiles.length === 0) {
        console.log('No migration files found in directory.');
        process.exit(0);
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('---');

    // Log each migration file in order
    migrationFiles.forEach((filename, index) => {
        console.log(`[${index + 1}/${migrationFiles.length}] ${filename}`);

        // Read and display a preview of the SQL content (first 2 lines)
        try {
            const content = readMigrationFile(migrationsDir, filename);
            const lines = content.split('\n').filter(line => line.trim() !== '');
            const preview = lines.length > 0 ? lines[0] : '(empty file)';

            console.log(`  Content preview: ${preview.substring(0, 80)}${preview.length > 80 ? '...' : ''}`);

            // Count SQL statements (approximate count by semicolons)
            const statementCount = (content.match(/;/g) || []).length;
            console.log(`  SQL statements: ${statementCount}`);
        } catch (error) {
            console.error(`  Error reading file: ${error.message}`);
        }

        console.log('---');
    });

    console.log('Migration planning complete.');
    console.log(`Would apply ${migrationFiles.length} migration(s) in the order shown above.`);
    console.log('\nTo actually apply these migrations, you would need to:');
    console.log('1. Connect to your database');
    console.log('2. Execute each SQL file in order');
    console.log('3. Track which migrations have been applied (e.g., in a migrations table)');
}

// Run the main function
main();

