/**
 * Load environment variables from .env.test file
 * @returns {Object} Environment variables object
 */
function loadEnvFile() {
    const envPath = '.env.test';

    if (!fs.existsSync(envPath)) {
        console.warn(`Warning: ${envPath} file not found.`);
        return {};
    }

    try {
        const envContent = fs.readFileSync(envPath, 'utf8');
        const envVars = {};

        // Parse .env file format (key=value, ignore comments)
        envContent.split('\n').forEach(line => {
            const trimmed = line.trim();
            // Skip empty lines and comments
            if (trimmed && !trimmed.startsWith('#')) {
                const equalIndex = trimmed.indexOf('=');
                if (equalIndex !== -1) {
                    const key = trimmed.substring(0, equalIndex).trim();
                    const value = trimmed.substring(equalIndex + 1).trim();
                    envVars[key] = value;
                }
            }
        });

        return envVars;
    } catch (error) {
        console.warn(`Warning: Failed to read ${envPath}: ${error.message}`);
        return {};
    }
}

/**
 * Parse database URL and extract connection details (just for logging)
 * @param {string} databaseUrl - Database connection string
 * @returns {Object} Parsed connection details
 */
function parseDatabaseUrl(databaseUrl) {
    try {
        // Parse the database URL format: postgres://user:password@host:port/database
        const url = new URL(databaseUrl);
        return {
            protocol: url.protocol.replace(':', ''),
            username: url.username,
            host: url.hostname,
            port: url.port,
            database: url.pathname.replace('/', ''),
            // Don't log the actual password for security
            hasPassword: !!url.password
        };
    } catch (error) {
        return {
            error: `Invalid database URL format: ${error.message}`
        };
