            hostname: url.hostname,
            port: url.port,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'User-Agent': 'MigrationAudit/1.0'
            }
        };

        const req = (url.protocol === 'https:' ? https : http).request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                const result = {
                    statusCode: res.statusCode,
                    statusMessage: res.statusMessage,
                    headers: res.headers,
