#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        console.log(`Migration script starting...`);
        console.log(`Migrations directory: ${this.migrationsDir}\n`);
    }

    /**
     * Get all SQL files from the migrations directory in order
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' not found!`);
                process.exit(1);
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files and sort them numerically by prefix
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .map(file => {
                    const filePath = path.join(this.migrationsDir, file);
                    // Extract numeric prefix for sorting
                    const match = file.match(/^(\d+)_/);
                    const order = match ? parseInt(match[1], 10) : Infinity;
                    return { file, filePath, order };
                })
                .sort((a, b) => a.order - b.order); // Sort by numeric prefix

            return sqlFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('Would apply the following migrations in order:');
        console.log('='.repeat(50));

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found in migrations directory.');
            return;
        }

        // Log each migration file
        migrationFiles.forEach((migration, index) => {
            console.log(`${index + 1}. ${migration.file}`);

            // Optional: Read and preview first few lines of SQL content
            try {
                const content = fs.readFileSync(migration.filePath, 'utf8');
                const firstLine = content.split('\n')[0]?.trim();
                if (firstLine) {
                    console.log(`   Preview: ${firstLine}`);
                }
            } catch (error) {
                console.log(`   [Could not read file content]`);
            }
            console.log('');
        });

        console.log(`Total: ${migrationFiles.length} migration(s) would be applied.`);
        console.log('='.repeat(50));
        console.log('Note: This is a dry run. No SQL commands have been executed.');
    }

    /**
     * Main execution method
     */
    run() {
        this.logMigrations();
    }
}

// Run the script
const migrationScript = new MigrationScript();
migrationScript.run();

