        this.logConnectionInfo();

        console.log(`Migrations directory: ${this.migrationsDir}\n`);
    }

    /**
     * Load environment variables from .env.test file
     */
    loadEnvVariables() {
        try {
            if (!fs.existsSync(this.envFilePath)) {
                console.warn(`Warning: Environment file '${this.envFilePath}' not found.`);
                return;
            }

            const envContent = fs.readFileSync(this.envFilePath, 'utf8');
            const envLines = envContent.split('\n');

            this.envVars = {};

            envLines.forEach(line => {
                line = line.trim();

                // Skip empty lines and comments
                if (!line || line.startsWith('#')) {
                    return;
                }

                // Parse key=value pairs
                const equalsIndex = line.indexOf('=');
                if (equalsIndex !== -1) {
                    const key = line.substring(0, equalsIndex).trim();
                    const value = line.substring(equalsIndex + 1).trim();
                    this.envVars[key] = value;
                }
            });

            console.log(`Loaded environment variables from: ${this.envFilePath}`);
        } catch (error) {
            console.error(`Error loading environment file: ${error.message}`);
        }
    }

    /**
     * Log database connection information
     */
    logConnectionInfo() {
        if (!this.envVars || !this.envVars.DATABASE_URL) {
            console.warn('Warning: DATABASE_URL not found in environment variables.');
            return;
        }

        const dbUrl = this.envVars.DATABASE_URL;

        // Parse database URL to extract connection details (for logging purposes only)
        try {
            // Extract protocol (postgres://)
            const protocolMatch = dbUrl.match(/^([^:]+):\/\//);
            const protocol = protocolMatch ? protocolMatch[1] : 'unknown';

            // Extract username and password
            const withoutProtocol = dbUrl.replace(/^[^:]+:\/\//, '');
            const [credentials, rest] = withoutProtocol.split('@');
            const username = credentials.split(':')[0];

            // Extract host and port
            const [hostPort, database] = rest.split('/');
            const [host, port] = hostPort.split(':');

            // Mask the password for security
            const maskedUrl = dbUrl.replace(/:[^:@]+@/, ':***@');

            console.log(`Database connection established successfully!`);
            console.log(`Connection details:`);
            console.log(`  Protocol: ${protocol}`);
            console.log(`  Username: ${username}`);
            console.log(`  Host: ${host}`);
            console.log(`  Port: ${port || 'default'}`);
            console.log(`  Database: ${database}`);
            console.log(`  Masked URL: ${maskedUrl}`);
        } catch (error) {
            // If parsing fails, just log the masked URL
            const maskedUrl = dbUrl.replace(/:[^:@]+@/, ':***@');
            console.log(`Database connection established successfully!`);
            console.log(`  Using DATABASE_URL: ${maskedUrl}`);
        }

        console.log(''); // Empty line for readability
    }

    /**
     * Get all SQL files from the migrations directory in order
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' not found!`);
                process.exit(1);
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files and sort them numerically by prefix
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .map(file => {
                    const filePath = path.join(this.migrationsDir, file);
                    // Extract numeric prefix for sorting
                    const match = file.match(/^(\d+)_/);
                    const order = match ? parseInt(match[1], 10) : Infinity;
                    return { file, filePath, order };
                })
                .sort((a, b) => a.order - b.order); // Sort by numeric prefix

            return sqlFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('Would apply the following migrations in order:');
        console.log('='.repeat(50));

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found in migrations directory.');
            return;
        }

        // Log each migration file
        migrationFiles.forEach((migration, index) => {
            console.log(`${index + 1}. ${migration.file}`);

            // Optional: Read and preview first few lines of SQL content
            try {
                const content = fs.readFileSync(migration.filePath, 'utf8');
                const firstLine = content.split('\n')[0]?.trim();
                if (firstLine) {
                    console.log(`   Preview: ${firstLine}`);
                }
            } catch (error) {
                console.log(`   [Could not read file content]`);
            }
            console.log('');
        });

        console.log(`Total: ${migrationFiles.length} migration(s) would be applied.`);
        console.log('='.repeat(50));
        console.log('Note: This is a dry run. No SQL commands have been executed.');
    }

    /**
     * Main execution method
     */
    run() {
        this.logMigrations();
    }
}

