#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * 
 * Features:
 * - Reads all .sql files from migrations directory
 * - Sorts files alphabetically/numerically for proper order
 * - Logs each filename before it would be applied
 * - Provides stats about migrations
 */

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
        this.migrations = [];
        this.databaseUrl = null;

        // Load environment variables from .env.test
        this.loadEnvVariables();
    }

    /**
     * Load environment variables from .env.test file
     */
    loadEnvVariables() {
        try {
            const envPath = path.join(process.cwd(), '.env.test');
            if (fs.existsSync(envPath)) {
                const envContent = fs.readFileSync(envPath, 'utf8');
                const lines = envContent.split('\n');

                lines.forEach(line => {
                    // Skip comments and empty lines
                    const trimmedLine = line.trim();
                    if (!trimmedLine || trimmedLine.startsWith('#')) {
                        return;
                    }

                    // Parse key=value pairs
                    const equalsIndex = trimmedLine.indexOf('=');
                    if (equalsIndex !== -1) {
                        const key = trimmedLine.substring(0, equalsIndex).trim();
                        const value = trimmedLine.substring(equalsIndex + 1).trim();

                        if (key === 'DATABASE_URL') {
                            this.databaseUrl = value;
                            console.log(`✅ Loaded DATABASE_URL from .env.test`);
                        }
                    }
                });
            } else {
                console.warn(`⚠️  .env.test file not found. Using default settings.`);
            }
        } catch (error) {
            console.warn(`⚠️  Error loading .env.test file: ${error.message}`);
        }
    }

    /**
     * Log connection status based on loaded DATABASE_URL
     */
    logConnectionStatus() {
        console.log('🔌 Database Connection Status:');
        console.log('-'.repeat(30));

        if (this.databaseUrl) {
            // Extract parts of the URL for logging (not revealing sensitive info)
            try {
                const url = new URL(this.databaseUrl);
                console.log(`✅ Connected to: ${url.protocol}//${url.host}${url.pathname}`);

                // Mask protocol-specific credentials for security
                if (url.username) {
                    console.log(`   Username: ${url.username}`);
                }

                console.log(`   Database: ${url.pathname.replace(/^\//, '') || 'default'}`);

                // Check if it's a test canary value
                if (this.databaseUrl.includes('CANARY')) {
                    console.log(`   ⚠️  Using test/canary credentials`);
                }
            } catch (error) {
                console.log(`✅ Loaded DATABASE_URL (${this.databaseUrl.length} chars)`);
            }
        } else {
            console.log(`❌ No DATABASE_URL found in .env.test`);
            console.log(`   Please ensure .env.test contains a DATABASE_URL variable`);
        }
        console.log('');
    }

    /**
     * Discover migration files in the migrations directory
     */
    discoverMigrations() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`❌ Migrations directory "${this.migrationsDir}" not found.`);
                console.log('💡 Tip: Create a "migrations" directory and add SQL files.');
                return [];
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log(`📁 No SQL files found in "${this.migrationsDir}".`);
                return [];
            }

            // Sort files alphabetically (which also works for timestamp/number prefixed files)
            sqlFiles.sort();

            return sqlFiles;
        } catch (error) {
            console.error(`❌ Error reading migrations directory:`, error.message);
            return [];
        }
    }

    /**
     * Get migration information for each file
     */
    getMigrationInfo(filename) {
        const filePath = path.join(this.migrationsDir, filename);
        const stats = fs.statSync(filePath);

        return {
            filename,
            filePath,
            size: stats.size,
            modified: stats.mtime
        };
    }

    /**
     * Simulate applying migrations (just logs what would happen)
     */
    simulateMigrations() {
        console.log('🚀 Database Migration Script');
        console.log('='.repeat(50));

        // Log connection status
        this.logConnectionStatus();

        // Discover migration files
        const migrationFiles = this.discoverMigrations();

        if (migrationFiles.length === 0) {
            return;
        }

        console.log(`📚 Found ${migrationFiles.length} migration file(s):\n`);

        // Log each migration that would be applied
        migrationFiles.forEach((filename, index) => {
            const info = this.getMigrationInfo(filename);
            const migrationNumber = (index + 1).toString().padStart(2, '0');

            console.log(`  ${migrationNumber}. 📄 ${filename}`);
            console.log(`     📏 Size: ${Math.round(info.size / 1024 * 100) / 100} KB`);

            // Show a preview of the SQL content (first 3 lines)
            try {
                const content = fs.readFileSync(info.filePath, 'utf8');
                const lines = content.split('\n').slice(0, 3);
                lines.forEach((line, i) => {
                    if (line.trim()) {
                        console.log(`     ${i === 0 ? '📝' : '   '} ${line.trim().substring(0, 80)}${line.length > 80 ? '...' : ''}`);
                    }
                });
                if (content.split('\n').length > 3) {
                    console.log(`     ...`);
                }
            } catch (error) {
                console.log(`     ❌ Error reading file: ${error.message}`);
            }

            console.log(); // Empty line between migrations
        });

        console.log('='.repeat(50));
        console.log('📊 Migration Summary:');
        console.log(`   • Total migrations: ${migrationFiles.length}`);
        console.log(`   • First migration: ${migrationFiles[0]}`);
        console.log(`   • Last migration: ${migrationFiles[migrationFiles.length - 1]}`);
        console.log();
        console.log('💡 This is a simulation. To actually apply migrations:');
        console.log('   1. Connect to your database');
        console.log('   2. Execute the SQL from each file in order');
        console.log('   3. Track which migrations have been applied (e.g., in a migrations table)');
    }

    /**
     * Run the migration script
     */
    run() {
        this.simulateMigrations();
    }
}

// If this script is run directly (not imported as a module)
if (require.main === module) {
    const runner = new MigrationRunner();
    runner.run();
}

// Export for use as a module
module.exports = MigrationRunner;

