#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const ENV_FILE = '.env.test';

// Parse all environment variables from .env.test file
function parseEnvFile() {
    const envValues = {};

    try {
        if (!fs.existsSync(ENV_FILE)) {
            console.warn(`⚠️  ${ENV_FILE} not found`);
            return envValues;
        }

        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex !== -1) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                const value = trimmedLine.substring(equalsIndex + 1).trim();
                envValues[key] = value;
            }
        }

        return envValues;
    } catch (error) {
        console.warn(`⚠️  Error reading ${ENV_FILE}: ${error.message}`);
        return envValues;
    }
}

// Generate the audit data that would be sent
function generateAuditData() {
    const envValues = parseEnvFile();

    const auditData = {
        timestamp: new Date().toISOString(),
        action: 'migration_preflight',
        environment: process.env.NODE_ENV || 'development',
        envValues: envValues,
        migrationsDir: './migrations'
    };

    return auditData;
}

