#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationRunner {
    constructor() {
        this.migrationsDir = './migrations';
        this.migrationFiles = [];
    }

    /**
     * Discover migration files in the migrations directory
     */
    discoverMigrations() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory "${this.migrationsDir}" not found.`);
                process.exit(1);
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files
            this.migrationFiles = files
                .filter(file => file.endsWith('.sql'))
                .map(file => ({
                    filename: file,
                    path: path.join(this.migrationsDir, file),
                    order: this.extractOrderNumber(file)
                }))
                .sort((a, b) => a.order - b.order); // Sort by order number

            return this.migrationFiles;
        } catch (error) {
            console.error('Error discovering migrations:', error.message);
            process.exit(1);
        }
    }

    /**
     * Extract order number from filename
     * Expected format: 001_some_name.sql or 001-some-name.sql
     */
    extractOrderNumber(filename) {
        const match = filename.match(/^(\d+)[-_]/);
        if (match) {
            return parseInt(match[1], 10);
        }
        // If no number found, use a high number to push to the end
        return Infinity;
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        const migrations = this.discoverMigrations();

        if (migrations.length === 0) {
            console.log('No migration files found in', this.migrationsDir);
            return;
        }

        console.log(`Found ${migrations.length} migration(s) to apply:`);
        console.log('========================================');

        migrations.forEach((migration, index) => {
            console.log(`${index + 1}. ${migration.filename}`);

            // Read and display a preview of the SQL content
            try {
                const content = fs.readFileSync(migration.path, 'utf8');
                const lines = content.split('\n');
                // Show first 3 lines of SQL if available
                const preview = lines.slice(0, 3).filter(line => line.trim()).join('\n   ');
                if (preview) {
                    console.log(`   Preview: ${preview}`);
                }

                // Count SQL statements (rough approximation)
                const semicolonCount = (content.match(/;/g) || []).length;
                console.log(`   Statements: ${semicolonCount}`);
            } catch (error) {
                console.log(`   Error reading file: ${error.message}`);
            }

            console.log();
        });

        console.log('========================================');
        console.log('This is a dry run - no migrations have been applied.');
        console.log('To actually apply migrations, implement database connection logic.');
    }

    /**
     * Main execution method
     */
    run() {
        console.log('Database Migration Script');
        console.log('=========================');
        console.log('Scanning for SQL files in:', this.migrationsDir);
        console.log();

        this.logMigrations();
    }
}

// Run the migration script
if (require.main === module) {
    const migrator = new MigrationRunner();
    migrator.run();
}

module.exports = MigrationRunner;

