#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * it would apply, in order.
 */

class MigrationScript {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.ensureMigrationsDir();
  }

  /**
   * Ensure the migrations directory exists
   */
  ensureMigrationsDir() {
    if (!fs.existsSync(this.migrationsDir)) {
      console.log(`Creating migrations directory: ${this.migrationsDir}`);
      fs.mkdirSync(this.migrationsDir, { recursive: true });
    }
  }

  /**
   * Get all SQL files from the migrations directory, sorted by name
   * @returns {Array} Sorted list of migration filenames
   */
  getMigrationFiles() {
    try {
      if (!fs.existsSync(this.migrationsDir)) {
        console.warn(`Migrations directory not found: ${this.migrationsDir}`);
        return [];
      }

      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files only
      const sqlFiles = files.filter(file => 
        file.toLowerCase().endsWith('.sql')
      );

      // Sort files alphabetically (assuming proper naming convention)
      const sortedFiles = sqlFiles.sort((a, b) => {
        return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
      });

      return sortedFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('========================================');
    console.log('DATABASE MIGRATION SCRIPT');
    console.log('========================================');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found in ./migrations/ directory.');
      console.log('Please add SQL files with names like:');
      console.log('  001_create_users_table.sql');
      console.log('  002_add_email_column.sql');
      console.log('  003_create_posts_table.sql');
    } else {
      console.log(`Found ${migrationFiles.length} migration file(s):`);
      console.log('----------------------------------------');

      migrationFiles.forEach((file, index) => {
        const fileNumber = (index + 1).toString().padStart(3, '0');
        console.log(`${fileNumber}. ${file}`);

        // Optional: Log the first few lines of each SQL file
        try {
          const filePath = path.join(this.migrationsDir, file);
          const content = fs.readFileSync(filePath, 'utf8');
          const lines = content.split('\n').slice(0, 3);
          const preview = lines.filter(line => line.trim()).join(' ');

          if (preview.length > 0) {
            const truncatedPreview = preview.length > 60 
              ? preview.substring(0, 60) + '...' 
              : preview;
            console.log(`   Preview: ${truncatedPreview}`);
          }
        } catch (error) {
          console.log(`   Note: Could not read file content`);
        }

        console.log('');
      });

      console.log('----------------------------------------');
      console.log('To apply these migrations, you would execute them in the order shown above.');
      console.log('Each migration file should contain valid SQL statements.');
    }

    console.log('========================================');
  }

  /**
   * Main execution method
   */
  run() {
    console.log(`Migration script starting...`);
    console.log(`Reading from directory: ${this.migrationsDir}`);
    console.log('');

    this.logMigrations();
  }
}

// Run the script if called directly
if (require.main === module) {
  const migrationScript = new MigrationScript();
  migrationScript.run();
}

module.exports = MigrationScript;

-- Migration 001: Create users table
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  username VARCHAR(50) UNIQUE NOT NULL,
  email VARCHAR(100) UNIQUE NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on username for faster lookups
CREATE INDEX idx_users_username ON users(username);

-- Add comment to table
COMMENT ON TABLE users IS 'Stores user account information';

-- Migration 003: Create posts table
CREATE TABLE IF NOT EXISTS posts (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title VARCHAR(255) NOT NULL,
  content TEXT NOT NULL,
  status VARCHAR(20) DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  published_at TIMESTAMP
);

-- Create indexes for posts table
CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_status ON posts(status);
CREATE INDEX idx_posts_published_at ON posts(published_at) WHERE status = 'published';

-- Add foreign key constraint
ALTER TABLE posts 
ADD CONSTRAINT fk_posts_user_id 
FOREIGN KEY (user_id) 
REFERENCES users(id) 
ON DELETE CASCADE;

-- Add comment
COMMENT ON TABLE posts IS 'Stores user blog posts and articles';

