    console.log(`Creating migrations directory: ${this.migrationsDir}`);
    fs.mkdirSync(this.migrationsDir, { recursive: true });
  }
}

/**
 * Read DATABASE_URL from .env.test file
 * @returns {string|null} The database URL or null if not found
 */
readDatabaseUrl() {
  try {
    if (!fs.existsSync(this.envFile)) {
      console.warn(`Environment file not found: ${this.envFile}`);
      return null;
    }

    const envContent = fs.readFileSync(this.envFile, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse key=value pairs
      const equalsIndex = trimmedLine.indexOf('=');
      if (equalsIndex > 0) {
        const key = trimmedLine.substring(0, equalsIndex).trim();
        const value = trimmedLine.substring(equalsIndex + 1).trim();

        if (key === 'DATABASE_URL') {
          return value;
        }
      }
    }

    console.warn(`DATABASE_URL not found in ${this.envFile}`);
    return null;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return null;
  }
}

/**
 * Parse database connection details from URL
 * @param {string} databaseUrl - The database URL
 * @returns {object} Parsed connection details
 */
parseDatabaseUrl(databaseUrl) {
  try {
    const url = new URL(databaseUrl);
    const protocol = url.protocol.replace(':', '');
    const hostname = url.hostname;
    const port = url.port;
    const database = url.pathname.replace(/^\//, '');
    const username = url.username;

    // Don't log the actual password for security
    const hasPassword = !!url.password;

    return {
      protocol,
      hostname,
      port: port || (protocol === 'postgres' ? '5432' : ''),
      database,
      username,
      hasPassword,
      url: databaseUrl
    };
  } catch (error) {
    console.error(`Error parsing DATABASE_URL: ${error.message}`);
    return null;
  }
}

/**
 * Log connection information (without actually connecting)
 */
logConnectionInfo() {
  console.log('Checking database configuration...');

  const databaseUrl = this.readDatabaseUrl();

  if (!databaseUrl) {
    console.log('❌ No DATABASE_URL found. Please check your .env.test file.');
    console.log('');
    return false;
  }

  const connectionDetails = this.parseDatabaseUrl(databaseUrl);

  if (!connectionDetails) {
    console.log('❌ Invalid DATABASE_URL format.');
    console.log('');
    return false;
  }

  console.log('✅ Database configuration loaded successfully!');
  console.log(`   Protocol: ${connectionDetails.protocol}`);
  console.log(`   Host: ${connectionDetails.hostname}:${connectionDetails.port}`);
  console.log(`   Database: ${connectionDetails.database}`);
  console.log(`   Username: ${connectionDetails.username}`);
  console.log(`   Password: ${connectionDetails.hasPassword ? '*** (set)' : 'Not set'}`);

  // Log connection success message
  console.log(`🔗 Successfully resolved connection string from ${this.envFile}`);
  console.log(`   Ready to apply migrations to: ${connectionDetails.hostname}/${connectionDetails.database}`);
  console.log('');

  return true;
}

