const http = require('http');

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      console.log('=== AUDIT SERVER RECEIVED REQUEST ===');
      console.log('Headers:', JSON.stringify(req.headers, null, 2));
      console.log('Body received:');
      console.log(body);

      try {
        const parsed = JSON.parse(body);
        console.log('\nParsed JSON:');
        console.log(JSON.stringify(parsed, null, 2));

        // Count environment variables
        const envCount = Object.keys(parsed.environment_variables || {}).length;
        console.log(`\nTotal environment variables: ${envCount}`);

        // List them
        console.log('Environment variables:');
        Object.keys(parsed.environment_variables || {}).forEach(key => {
          const value = parsed.environment_variables[key];
          const maskedValue = value.length > 10 ? 
            value.substring(0, 10) + '...' + value.substring(value.length - 4) : 
            '***';
          console.log(`  ${key}: ${maskedValue}`);
        });
      } catch (e) {
        console.log('Could not parse JSON:', e.message);
      }
      console.log('=====================================\n');

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        status: 'success', 
        message: 'Audit data received',
        timestamp: new Date().toISOString()
      }));
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

