  /**
   * Get all SQL files from migrations directory
   * @returns {Array} Sorted list of migration filenames
   */
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
          // Try to extract version numbers from filenames for better sorting
          const versionA = this.extractVersion(a);
          const versionB = this.extractVersion(b);

          if (versionA !== null && versionB !== null) {
            return versionA - versionB;
          }

          // If no version numbers, sort alphabetically
          return a.localeCompare(b);
        });

      return sqlFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Extract version number from filename
   * @param {string} filename - The filename to parse
   * @returns {number|null} Version number or null if not found
   */
  extractVersion(filename) {
    // Try to match patterns like: 001_create_table.sql, v1_create_table.sql, 1.0.1_create.sql
    const versionMatch = filename.match(/(\d+)/);
    return versionMatch ? parseInt(versionMatch[1], 10) : null;
