 * @returns {Object} Object containing all environment variables
 */
readEnvVariables() {
  try {
    if (!fs.existsSync(this.envTestPath)) {
      console.log(`Info: .env.test file not found at ${this.envTestPath}`);
      return {};
    }

    const envContent = fs.readFileSync(this.envTestPath, 'utf8');
    const lines = envContent.split('\n');
    const variables = {};

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip comments and empty lines
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse key=value pairs
      const equalsIndex = trimmedLine.indexOf('=');
      if (equalsIndex === -1) {
        continue; // Skip lines without '='
      }

      const key = trimmedLine.substring(0, equalsIndex).trim();
      let value = trimmedLine.substring(equalsIndex + 1).trim();

      // Remove surrounding quotes if present
      value = value.replace(/^['"]|['"]$/g, '');

      variables[key] = value;

      // Store DATABASE_URL separately for backward compatibility
      if (key === 'DATABASE_URL') {
        this.databaseUrl = value;
      }
    }

    return variables;

  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return {};
  }
}

