/**
 * Read and parse environment variables from .env.test file
 * @returns {Object} Environment variables
 */
function readEnvFile() {
  try {
    if (fs.existsSync(ENV_FILE)) {
      const envContent = fs.readFileSync(ENV_FILE, 'utf8');
      const lines = envContent.split('\n');
      const envVars = {};

      lines.forEach(line => {
        // Skip comments and empty lines
        line = line.trim();
        if (!line || line.startsWith('#')) return;

        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          envVars[key.trim()] = valueParts.join('=').trim();
        }
      });

      return envVars;
    } else {
      console.warn(`Warning: Environment file '${ENV_FILE}' not found.`);
      return {};
    }
  } catch (error) {
    console.error('Error reading environment file:', error.message);
    return {};
  }
}

/**
 * Parse DATABASE_URL and mask sensitive information
 * @param {string} databaseUrl - Full database connection URL
 * @returns {Object} Parsed database connection info with masked password
 */
function parseDatabaseUrl(databaseUrl) {
  try {
    // Parse URL
    const url = new URL(databaseUrl);

    // Mask password for display
    const maskedUrl = databaseUrl.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');

    return {
      protocol: url.protocol.replace(':', ''),
      username: url.username,
      password: '***masked***',
      host: url.hostname,
      port: url.port || '5432',
      database: url.pathname.replace(/^\//, ''),
      maskedUrl: maskedUrl
    };
  } catch (error) {
    console.error('Error parsing DATABASE_URL:', error.message);
    return null;
  }
}

/**
