/**
 * Read DATABASE_URL from environment file
 * @returns {string|null} DATABASE_URL value or null if not found
 */
function getDatabaseUrl() {
  try {
    if (fs.existsSync(ENV_FILE)) {
      const envContent = fs.readFileSync(ENV_FILE, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) continue;

        const [key, ...valueParts] = trimmedLine.split('=');
        if (key.trim() === 'DATABASE_URL' && valueParts.length > 0) {
          return valueParts.join('=').trim();
        }
      }
    }
    return null;
  } catch (error) {
    console.error('Error reading environment file:', error.message);
    return null;
  }
}

