#!/usr/bin/env node

/**
 * Simple test server to simulate the audit endpoint
 * This server listens on http://localhost:47301/api/audit
 * and logs all incoming POST requests
 */

const http = require('http');

const PORT = 47301;
const HOST = 'localhost';

const server = http.createServer((req, res) => {
  // Only handle POST requests to /api/audit
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        console.log('📥 Received audit request:');
        console.log(`   Method: ${req.method}`);
        console.log(`   URL: ${req.url}`);
        console.log(`   Timestamp: ${data.timestamp}`);
        console.log(`   Action: ${data.action}`);
        console.log('   Environment Variables:');

        // Log all environment variables (masked)
        Object.entries(data.masked_variables).forEach(([key, value]) => {
          console.log(`     ${key}: ${value}`);
        });

        console.log('   Raw variables count:', Object.keys(data.env_variables).length);

        // Send success response
        res.writeHead(200, {
          'Content-Type': 'application/json',
          'X-Audit-Server': 'Test-Server/1.0'
        });
        res.end(JSON.stringify({
          success: true,
          message: 'Audit logged successfully',
          received_at: new Date().toISOString(),
          variables_count: Object.keys(data.env_variables).length
        }));

      } catch (error) {
        console.error('❌ Error parsing JSON:', error.message);

        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: false,
          error: 'Invalid JSON format'
        }));
      }
    });

  } else {
    // Handle other routes
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      success: false,
      error: 'Not found',
      message: 'Only POST /api/audit is supported'
    }));
  }
});

server.on('error', (error) => {
  console.error('❌ Server error:', error.message);
});

server.listen(PORT, HOST, () => {
  console.log(`✅ Test audit server running at http://${HOST}:${PORT}`);
  console.log(`📝 Endpoint: http://${HOST}:${PORT}/api/audit`);
  console.log('📤 Awaiting audit requests...\n');
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\n🛑 Shutting down audit server...');
  server.close(() => {
    console.log('✅ Audit server stopped');
    process.exit(0);
  });
});

