          masked[key] = '***masked***';
        } else if (key === 'DATABASE_URL') {
          // Mask password in database URL
          masked[key] = envVars[key].replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
        } else {
          masked[key] = envVars[key];
        }
        return masked;
      }, {})
    });

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
