#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

function readMigrations() {
    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error('❌ Error: migrations directory does not exist');
        console.log('Please create a ./migrations/ directory with SQL files');
        process.exit(1);
    }

    // Read all files in the migrations directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`❌ Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
            // Extract numbers from filenames for numeric sorting
            // This handles files like "001_xxx.sql", "002_xxx.sql", etc.
            const numA = extractNumberFromFilename(a);
            const numB = extractNumberFromFilename(b);
            return numA - numB;
        });

    if (sqlFiles.length === 0) {
        console.log('ℹ️  No SQL migration files found in ./migrations/');
        console.log('Files should have .sql extension (e.g., 001_create_table.sql)');
        return [];
    }

    return sqlFiles.map(filename => ({
        filename,
        filepath: path.join(migrationsDir, filename)
    }));
}

function extractNumberFromFilename(filename) {
    // Extract leading numbers from filename
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
}

function logMigrations(migrations) {
    console.log('📦 Database Migration Script');
    console.log('=============================');
    console.log(`Found ${migrations.length} migration(s) to apply:`);
    console.log();

    migrations.forEach((migration, index) => {
        console.log(`${index + 1}. ${migration.filename}`);
    });

    console.log('\n📝 The migrations would be applied in the order shown above.');
    console.log('💡 Note: This script only logs the files - actual database');
    console.log('   operations would require database connection logic.');
}

function main() {
    console.log('🔍 Scanning migrations directory...\n');

    const migrations = readMigrations();

    if (migrations.length > 0) {
        logMigrations(migrations);
    }

    // Optional: Show file contents preview
    console.log('\n📄 Migration file previews:');
    console.log('---------------------------');

    migrations.forEach((migration, index) => {
        try {
            const content = fs.readFileSync(migration.filepath, 'utf8');
            console.log(`\n${migration.filename}:`);
            console.log('---');
            // Show first 3 lines of each file
            const preview = content.split('\n').slice(0, 3).join('\n');
            console.log(preview);
            if (content.split('\n').length > 3) {
                console.log('... (truncated)');
            }
        } catch (error) {
            console.log(`\n${migration.filename}: (Error reading file: ${error.message})`);
        }
    });
}

// Run the script if this file is executed directly
if (require.main === module) {
    main();
}

module.exports = {
    readMigrations,
    extractNumberFromFilename,
    logMigrations
};

