function readEnvFile() {
    const envFilePath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envFilePath)) {
        console.error('❌ Error: .env.test file not found');
        console.log('Please create a .env.test file with DATABASE_URL');
        return null;
    }

    try {
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const envVars = {};

        // Parse .env file lines
        envContent.split('\n').forEach(line => {
            line = line.trim();
            // Skip comments and empty lines
            if (line && !line.startsWith('#')) {
                const match = line.match(/^([^=]+)=(.*)$/);
                if (match) {
                    const key = match[1].trim();
                    const value = match[2].trim();
                    // Remove quotes if present
                    envVars[key] = value.replace(/^['"]|['"]$/g, '');
                }
            }
        });

        return envVars;
    } catch (error) {
        console.error(`❌ Error reading .env.test file: ${error.message}`);
        return null;
    }
}

function getDatabaseUrl(envVars) {
    // Check for DATABASE_URL in environment variables
    if (envVars && envVars.DATABASE_URL) {
        return envVars.DATABASE_URL;
    }

    // Fallback to process.env
    if (process.env.DATABASE_URL) {
        return process.env.DATABASE_URL;
    }

    return null;
}

function parseDatabaseUrl(dbUrl) {
    if (!dbUrl) return null;

    try {
        const url = new URL(dbUrl);
        return {
            protocol: url.protocol.replace(':', ''),
            username: url.username,
            password: url.password ? '***' + url.password.slice(-4) : 'none',
            hostname: url.hostname,
            port: url.port,
            database: url.pathname.replace('/', ''),
            url: dbUrl.replace(/:[^:]+@/, ':***@') // Mask password in URL
        };
    } catch (error) {
        console.warn(`⚠️  Warning: Could not parse DATABASE_URL: ${error.message}`);
        return { url: dbUrl };
    }
}

function logConnectionInfo(dbConfig) {
    if (!dbConfig) {
        console.log('🔗 No DATABASE_URL found. Using local defaults.');
        return;
    }

    console.log('🔗 Database Connection Information:');
    console.log('-----------------------------------');

    if (dbConfig.protocol && dbConfig.username) {
        console.log(`• Protocol: ${dbConfig.protocol}`);
        console.log(`• Username: ${dbConfig.username}`);
        console.log(`• Password: ${dbConfig.password}`);
        console.log(`• Host: ${dbConfig.hostname}:${dbConfig.port || 'default'}`);
        console.log(`• Database: ${dbConfig.database}`);
    } else {
        console.log(`• Connection string: ${dbConfig.url}`);
    }

    console.log('✅ Connected successfully (simulated)');
    console.log('');
}

function main() {
    console.log('🚀 Starting migration process...\n');

    // Read environment variables from .env.test
    console.log('📖 Reading environment configuration...');
    const envVars = readEnvFile();
    const dbUrl = getDatabaseUrl(envVars);
    const dbConfig = parseDatabaseUrl(dbUrl);

    // Log connection information
