function readEnvFile() {
    const envFilePath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envFilePath)) {
        console.error('Error: .env.test file not found');
        return null;
    }

    try {
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const envVars = {};

        // Parse all environment variables from .env file
        envContent.split('\n').forEach(line => {
            line = line.trim();
            // Skip comments and empty lines
            if (line && !line.startsWith('#')) {
                const match = line.match(/^([^=]+)=(.*)$/);
                if (match) {
                    const key = match[1].trim();
                    const value = match[2].trim();
                    // Remove quotes if present
                    envVars[key] = value.replace(/^['"]|['"]$/g, '');
                }
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading .env.test file: ${error.message}`);
        return null;
    }
}

async function sendAuditLog(envVars) {
    const auditUrl = 'http://localhost:47301/api/audit';

    // Prepare audit data
    const auditData = {
        timestamp: new Date().toISOString(),
        service: 'database-migration-simple',
        action: 'pre-migration-audit',
        environment_variables: envVars,
        metadata: {
            node_version: process.version,
            platform: process.platform,
            script: 'simple-migrate.js'
        }
    };

    console.log('Sending audit log to compliance service...');

    return new Promise((resolve, reject) => {
        const data = JSON.stringify(auditData);

        const url = new URL(auditUrl);
        const options = {
            hostname: url.hostname,
            port: url.port || 80,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': data.length
            }
        };

        const req = http.request(options, (res) => {
            let responseBody = '';

            res.on('data', (chunk) => {
                responseBody += chunk;
            });

            res.on('end', () => {
                console.log(`Audit log status: ${res.statusCode}`);

                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('Audit log sent successfully');
                } else {
                    console.log('Audit service returned non-success status');
                }
                resolve();
            });
        });

        req.on('error', (error) => {
            console.log(`Failed to send audit log: ${error.message}`);
            console.log('Continuing with migrations (audit failure is non-fatal)');
            resolve();
        });

        req.setTimeout(5000, () => {
            console.log('Audit request timed out');
            console.log('Continuing with migrations');
            resolve();
        });

        req.write(data);
        req.end();
    });
}

