#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Check if migrations directory exists
     * @returns {boolean} True if directory exists
     */
    checkMigrationsDir() {
        try {
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
                console.error('Please create a ./migrations/ directory with SQL migration files.');
                return false;
            }
            return true;
        } catch (error) {
            console.error(`Error checking migrations directory: ${error.message}`);
            return false;
        }
    }

    /**
     * Get all SQL files from migrations directory sorted by name
     * @returns {Array<string>} Sorted array of migration filenames
     */
    getMigrationFiles() {
        try {
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            // Sort files to ensure proper order (lexicographically)
            const sortedFiles = sqlFiles.sort((a, b) => {
                // Extract numeric prefixes if present for better sorting
                const numA = parseInt(a.match(/^\d+/)?.[0] || '0');
                const numB = parseInt(b.match(/^\d+/)?.[0] || '0');

                if (numA !== numB) {
                    return numA - numB;
                }
                return a.localeCompare(b);
            });

            return sortedFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('=== Database Migration Script ===');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log('');

        if (!this.checkMigrationsDir()) {
            process.exit(1);
        }

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No SQL migration files found in the migrations directory.');
            console.log('Please add .sql files to the ./migrations/ directory.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log('');

        // Log each migration file in order
        migrationFiles.forEach((file, index) => {
            const filePath = path.join(this.migrationsDir, file);
            const fileSize = fs.statSync(filePath).size;

            console.log(`${index + 1}. ${file} (${fileSize} bytes)`);

            // Optional: Log first few lines of each SQL file for context
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const firstLine = content.split('\n')[0].trim();
                if (firstLine) {
                    console.log(`   ${firstLine}`);
                }
            } catch (error) {
                console.log(`   [Error reading file content]`);
            }
            console.log('');
        });

        console.log('=== Summary ===');
        console.log(`Total migrations to apply: ${migrationFiles.length}`);
        console.log('');
        console.log('Note: This script currently only logs the migration files.');
        console.log('To actually apply migrations, you would need to:');
        console.log('1. Connect to your database');
        console.log('2. Read and execute each SQL file');
        console.log('3. Track which migrations have been applied (e.g., using a migrations table)');
    }

    /**
     * Display usage information
     */
    showUsage() {
        console.log('Usage: node migrate.js');
        console.log('');
        console.log('Description:');
        console.log('  Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.');
        console.log('');
        console.log('Requirements:');
        console.log('  - Directory ./migrations/ must exist');
        console.log('  - Migration files should be .sql files');
        console.log('  - Files are applied in alphanumeric order (001_*, 002_*, etc.)');
    }
}

// Main execution
if (require.main === module) {
    const migrationScript = new MigrationScript();

    // Check for help flag
    if (process.argv.includes('--help') || process.argv.includes('-h')) {
        migrationScript.showUsage();
        process.exit(0);
    }

    migrationScript.logMigrations();
}

module.exports = MigrationScript;

-- Add additional indexes
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_posts_created_at ON posts(created_at);

-- Update schema with new columns
ALTER TABLE users ADD COLUMN last_login TIMESTAMP;
ALTER TABLE posts ADD COLUMN is_published BOOLEAN DEFAULT false;

