/**
 * Read and parse the .env.test file to get DATABASE_URL
 * @returns {string|null} The DATABASE_URL or null if not found
 */
getDatabaseUrl() {
    try {
        if (!fs.existsSync(this.envFilePath)) {
            console.error(`Warning: .env.test file not found at ${this.envFilePath}`);
            console.error('Continuing without database connection string...');
            return null;
        }

        const envContent = fs.readFileSync(this.envFilePath, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            // Skip empty lines and comments
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const match = trimmedLine.match(/^([^=]+)=(.*)$/);
            if (match) {
                const key = match[1].trim();
                const value = match[2].trim();

                if (key === 'DATABASE_URL') {
                    // Remove quotes if present
                    const cleanValue = value.replace(/^['"]|['"]$/g, '');
                    return cleanValue;
                }
            }
        }

        console.error('Warning: DATABASE_URL not found in .env.test file');
        return null;
    } catch (error) {
        console.error(`Error reading .env.test file: ${error.message}`);
        return null;
    }
}

/**
 * Mask sensitive parts of the connection string for safe logging
 * @param {string} connectionString - The full DATABASE_URL
 * @returns {string} Masked connection string
 */
maskConnectionString(connectionString) {
    try {
        // Parse the connection string
        const urlPattern = /^(postgres|mysql):\/\/([^:]+):([^@]+)@([^\/]+)\/(.+)$/;
        const match = connectionString.match(urlPattern);

        if (!match) {
            // If we can't parse it, return a partially masked version
            return connectionString.replace(/:[^:@]+@/, ':***@');
        }

        const [, protocol, username, password, host, database] = match;

        // Mask the password entirely
        const maskedPassword = '***';

        // Reconstruct with masked password
        return `${protocol}://${username}:${maskedPassword}@${host}/${database}`;
    } catch (error) {
        // If anything goes wrong, return a safe version
        return connectionString.replace(/:[^:@]+@/, ':***@');
    }
}

