 * @returns {string|null} The DATABASE_URL or null if not found
 */
getDatabaseUrl() {
    try {
        if (!fs.existsSync(this.envFilePath)) {
            console.error(`Warning: .env.test file not found at ${this.envFilePath}`);
            console.error('Continuing without database connection string...');
            return null;
        }

        const envContent = fs.readFileSync(this.envFilePath, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
            // Skip empty lines and comments
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const match = trimmedLine.match(/^([^=]+)=(.*)$/);
            if (match) {
                const key = match[1].trim();
                const value = match[2].trim();

                if (key === 'DATABASE_URL') {
                    // Remove quotes if present
                    const cleanValue = value.replace(/^['"]|['"]$/g, '');
                    return cleanValue;
                }
            }
        }

        console.error('Warning: DATABASE_URL not found in .env.test file');
        return null;
    } catch (error) {
        console.error(`Error reading .env.test file: ${error.message}`);
        return null;
    }
}

