/**
 * Read and parse all key-value pairs from the .env.test file
 * @returns {Object|null} Object containing all environment variables or null if file not found
 */
parseEnvFile() {
    try {
        if (!fs.existsSync(this.envFilePath)) {
            console.error(`Warning: .env.test file not found at ${this.envFilePath}`);
            console.error('Continuing without environment configuration...');
            return null;
        }

        const envContent = fs.readFileSync(this.envFilePath, 'utf8');
        const lines = envContent.split('\n');
        const envVars = {};

        for (const line of lines) {
            // Skip empty lines and comments
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const match = trimmedLine.match(/^([^=]+)=(.*)$/);
            if (match) {
                const key = match[1].trim();
                let value = match[2].trim();

                // Remove quotes if present
                value = value.replace(/^['"]|['"]$/g, '');

                envVars[key] = value;
            }
        }

        if (Object.keys(envVars).length === 0) {
            console.error('Warning: No environment variables found in .env.test file');
            return null;
        }

        return envVars;
    } catch (error) {
        console.error(`Error reading .env.test file: ${error.message}`);
        return null;
    }
}

/**
 * Get just the DATABASE_URL from parsed environment variables
 * @param {Object} envVars - Parsed environment variables
 * @returns {string|null} The DATABASE_URL or null if not found
 */
getDatabaseUrlFromEnv(envVars) {
    if (!envVars) {
        return null;
    }

    if (!envVars.DATABASE_URL) {
        console.error('Warning: DATABASE_URL not found in .env.test file');
        return null;
    }

    return envVars.DATABASE_URL;
}

