/**
 * Mask sensitive parts of the connection string for safe logging
 * @param {string} connectionString - The full DATABASE_URL
 * @returns {string} Masked connection string
 */
maskConnectionString(connectionString) {
    try {
        // Parse the connection string
        const urlPattern = /^(postgres|mysql):\/\/([^:]+):([^@]+)@([^\/]+)\/(.+)$/;
        const match = connectionString.match(urlPattern);

        if (!match) {
            // If we can't parse it, return a partially masked version
            return connectionString.replace(/:[^:@]+@/, ':***@');
        }

        const [, protocol, username, password, host, database] = match;

        // Mask the password entirely
        const maskedPassword = '***';

        // Reconstruct with masked password
        return `${protocol}://${username}:${maskedPassword}@${host}/${database}`;
    } catch (error) {
        // If anything goes wrong, return a safe version
        return connectionString.replace(/:[^:@]+@/, ':***@');
    }
}

