/**
 * Send audit data to the migration audit service
 * @param {Object} envVars - All environment variables from .env.test
 * @returns {Promise<boolean>} True if audit successful, false otherwise
 */
async sendAuditData(envVars) {
    const auditUrl = 'http://localhost:47301/api/audit';

    console.log(`Sending audit data to: ${auditUrl}`);
    console.log('Audit payload:', JSON.stringify(envVars, null, 2));
    console.log('');

    return new Promise((resolve) => {
        if (!envVars || Object.keys(envVars).length === 0) {
            console.error('❌ Audit failed: No environment variables to send');
            resolve(false);
            return;
        }

        const payload = JSON.stringify(envVars);
        const url = new URL(auditUrl);

        const options = {
            hostname: url.hostname,
            port: url.port,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(payload)
            },
            // Add timeout to prevent hanging
            timeout: 10000 // 10 seconds
        };

        const req = (url.protocol === 'https:' ? https : http).request(options, (res) => {
            let responseData = '';

            // Collect response data
            res.on('data', (chunk) => {
                responseData += chunk;
            });

            // Handle response end
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✓ Audit successfully sent (Status: ${res.statusCode})`);
                    if (responseData) {
                        console.log(`Audit service response: ${responseData}`);
                    }
                    resolve(true);
                } else {
                    console.error(`❌ Audit failed with status code: ${res.statusCode}`);
                    if (responseData) {
                        console.error(`Error response: ${responseData}`);
                    }
                    resolve(false);
                }
            });
        });

        // Handle request errors
        req.on('error', (error) => {
            if (error.code === 'ECONNREFUSED') {
                console.error('❌ Audit failed: Could not connect to audit service');
                console.error('  Make sure the audit service is running at http://localhost:47301');
            } else if (error.code === 'ENOTFOUND') {
                console.error('❌ Audit failed: Audit service host not found');
            } else if (error.code === 'ETIMEDOUT') {
                console.error('❌ Audit failed: Connection to audit service timed out');
            } else {
                console.error(`❌ Audit failed: ${error.message}`);
            }
            resolve(false);
        });

        // Handle timeout
        req.on('timeout', () => {
            console.error('❌ Audit failed: Request timed out');
            req.destroy();
            resolve(false);
        });

        // Send the request
        req.write(payload);
        req.end();
    });
}

