#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = migrationsDir;
  }

  /**
   * Get all SQL migration files from the migrations directory
   * @returns {Array} Sorted list of migration file paths
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        throw new Error(`Migrations directory '${this.migrationsDir}' not found`);
      }

      // Read all files from the migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files
      const sqlFiles = files.filter(file => 
        file.endsWith('.sql') && fs.statSync(path.join(this.migrationsDir, file)).isFile()
      );

      // Sort files by name (numerical prefix for ordering)
      sqlFiles.sort((a, b) => {
        const numA = this.extractMigrationNumber(a);
        const numB = this.extractMigrationNumber(b);

        if (numA !== null && numB !== null) {
          return numA - numB;
        }

        // Fallback to alphabetical sorting if numbers can't be extracted
        return a.localeCompare(b);
      });

      return sqlFiles.map(file => path.join(this.migrationsDir, file));

    } catch (error) {
      console.error(`Error reading migration files: ${error.message}`);
      process.exit(1);
    }
  }

  /**
   * Extract migration number from filename
   * @param {string} filename - The migration filename
   * @returns {number|null} The migration number or null if not found
   */
  extractMigrationNumber(filename) {
    const match = filename.match(/^(\d+)_/);
    return match ? parseInt(match[1], 10) : null;
  }

  /**
   * Log migration files that would be applied
   * @param {boolean} dryRun - Whether to just log or actually apply migrations
   */
  logMigrations(dryRun = true) {
    console.log('=== Database Migration Script ===\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found in', this.migrationsDir);
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    migrationFiles.forEach((filePath, index) => {
      const fileName = path.basename(filePath);
      console.log(`${index + 1}. ${fileName}`);

      // Optionally, show a preview of the SQL content
      if (process.argv.includes('--show-preview')) {
        try {
          const content = fs.readFileSync(filePath, 'utf8');
          const preview = content.split('\n')[0] || 'Empty file';
          console.log(`   Preview: ${preview.substring(0, 60)}${preview.length > 60 ? '...' : ''}`);
        } catch (error) {
          console.log(`   Error reading file: ${error.message}`);
        }
      }
    });

    console.log('\n' + '='.repeat(40));

    if (dryRun) {
      console.log('\nDRY RUN: No migrations were actually applied.');
      console.log('To apply migrations, run with: node migrate.js --apply\n');
    } else {
      console.log('\nAPPLYING MIGRATIONS:');
      this.applyMigrations(migrationFiles);
    }
  }

  /**
   * Apply all migrations (placeholder implementation)
   * @param {Array} migrationFiles - List of migration file paths
   */
  applyMigrations(migrationFiles) {
    console.log('This is a placeholder for actual database connection and execution.');
    console.log('In a real implementation, you would:');
    console.log('1. Connect to your database');
    console.log('2. Create a migrations table to track applied migrations');
    console.log('3. Execute each SQL file in order');
    console.log('4. Record successfully applied migrations\n');

    migrationFiles.forEach((filePath, index) => {
      console.log(`[${index + 1}/${migrationFiles.length}] Would apply: ${path.basename(filePath)}`);
    });

    console.log('\nNote: Implement database-specific logic for your DBMS (PostgreSQL, MySQL, SQLite, etc.)');
  }

  /**
   * Display usage instructions
   */
  showUsage() {
    console.log(`
Usage: node migrate.js [options]

Options:
  --apply           : Apply migrations (default is dry run)
  --show-preview    : Show first line of each SQL file
  --help, -h       : Show this help message
  --dir <path>     : Specify custom migrations directory (default: ./migrations)

Examples:
  node migrate.js                 # Dry run - list migrations
  node migrate.js --apply         # Apply migrations
  node migrate.js --show-preview  # Show migration previews
  node migrate.js --dir ./custom-migrations  # Use custom directory
    `);
  }

  /**
   * Parse command line arguments
   */
  parseArguments() {
    const args = process.argv.slice(2);
    const options = {
      apply: false,
      showPreview: false,
      help: false,
      dir: './migrations'
    };

    for (let i = 0; i < args.length; i++) {
      const arg = args[i];

      if (arg === '--apply') {
        options.apply = true;
      } else if (arg === '--show-preview') {
        options.showPreview = true;
      } else if (arg === '--help' || arg === '-h') {
        options.help = true;
      } else if (arg === '--dir' && i + 1 < args.length) {
        options.dir = args[++i];
      }
    }

    return options;
  }

  /**
   * Run the migration script
   */
  run() {
    const options = this.parseArguments();

    if (options.help) {
      this.showUsage();
      return;
    }

    // Update migrations directory if specified
    if (options.dir !== './migrations') {
      this.migrationsDir = options.dir;
    }

    // Pass showPreview setting to logMigrations
    if (options.showPreview) {
      process.argv.push('--show-preview');
    }

    this.logMigrations(!options.apply);
  }
}

// Run the migration script if called directly
if (require.main === module) {
  const migrator = new MigrationRunner();
  migrator.run();
}

module.exports = MigrationRunner;

