#!/usr/bin/env node

/**
 * Simple Database Migration Script
 * 
 * Reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Reads DATABASE_URL from .env.test file.
 */

const fs = require('fs');
const path = require('path');

// Read DATABASE_URL from .env.test file
function readDatabaseUrl(envFile = '.env.test') {
  try {
    // Check if environment file exists
    if (!fs.existsSync(envFile)) {
      console.warn(`Warning: Environment file '${envFile}' not found`);
      return null;
    }

    // Read the environment file
    const envContent = fs.readFileSync(envFile, 'utf8');

    // Parse DATABASE_URL from the file
    const lines = envContent.split('\n');
    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip comments and empty lines
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Look for DATABASE_URL
      const match = trimmedLine.match(/^DATABASE_URL\s*=\s*(.+)$/);
      if (match) {
        const databaseUrl = match[1].trim();

        // Create a safe version for logging (hide password)
        const safeUrl = databaseUrl.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
        console.log(`✓ Read DATABASE_URL from ${envFile}: ${safeUrl}`);
        console.log('✓ Connection would be established successfully\n');

        return databaseUrl;
      }
    }

    console.warn(`Warning: DATABASE_URL not found in '${envFile}'`);
    return null;

  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return null;
  }
}

// Main execution
console.log('=== Simple Database Migration Script ===\n');

// Read and log connection information
readDatabaseUrl('.env.test');

// Define migrations directory
const migrationsDir = './migrations';

// Check if migrations directory exists
if (!fs.existsSync(migrationsDir)) {
  console.error(`Error: Migrations directory '${migrationsDir}' not found`);
  process.exit(1);
}

try {
  // Read all files from the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files that are actual files (not directories)
  const sqlFiles = files.filter(file => {
    const filePath = path.join(migrationsDir, file);
    return file.endsWith('.sql') && fs.statSync(filePath).isFile();
  });

  // Sort files by name (using numerical prefix if available)
  sqlFiles.sort((a, b) => {
    // Try to extract numbers from the beginning of filenames
    const numA = parseInt(a.match(/^(\d+)/)?.[1] || '0');
    const numB = parseInt(b.match(/^(\d+)/)?.[1] || '0');

    // If both have numbers, sort numerically
    if (!isNaN(numA) && !isNaN(numB)) {
      return numA - numB;
    }

    // Otherwise sort alphabetically
    return a.localeCompare(b);
  });

  console.log('Migration files to apply (in order):');
  console.log('=====================================\n');

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
  } else {
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal: ${sqlFiles.length} migration file(s)`);
  }

} catch (error) {
  console.error(`Error reading migration files: ${error.message}`);
  process.exit(1);
}

