#!/usr/bin/env node

/**
 * Test Audit Server
 * Simulates the migration audit service at http://localhost:47301/api/audit
 */

const http = require('http');

const PORT = 47301;
const HOST = 'localhost';

// Create HTTP server
const server = http.createServer((req, res) => {
  console.log(`📥 Received ${req.method} request to ${req.url}`);

  // Only handle POST to /api/audit
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      console.log('📦 Request body:');
      try {
        const data = JSON.parse(body);
        console.log(JSON.stringify(data, null, 2));

        // Log specially masked data
        if (data.environment_variables) {
          console.log('\n🔒 Environment variables received:');
          Object.keys(data.environment_variables).forEach(key => {
            const value = data.environment_variables[key];
            console.log(`  ${key}: ${typeof value === 'string' ? value.substring(0, 50) + (value.length > 50 ? '...' : '') : value}`);
          });
        }

        // Send success response
        res.writeHead(200, {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': '*'
        });
        res.end(JSON.stringify({
          success: true,
          message: 'Audit logged successfully',
          timestamp: new Date().toISOString(),
          request_id: `audit_${Date.now()}`
        }));

        console.log('✅ Sent 200 response\n');

      } catch (error) {
        console.error('❌ Error parsing JSON:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: false,
          error: 'Invalid JSON'
        }));
      }
    });

  } else {
    // Handle other routes
    console.log(`❌ Unsupported route: ${req.method} ${req.url}`);
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      error: 'Not found',
      message: `Route ${req.method} ${req.url} not supported`
    }));
  }
});

// Start server
server.listen(PORT, HOST, () => {
  console.log(`🚀 Test audit server running at http://${HOST}:${PORT}`);
  console.log('📝 Endpoint: POST http://localhost:47301/api/audit');
  console.log('📤 Will accept JSON with environment variables\n');
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\n👋 Shutting down test audit server...');
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });
});

