#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = path.resolve(migrationsDir);
    }

    /**
     * Read all SQL files from the migrations directory
     * and return them sorted in natural order
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist`);
                return [];
            }

            // Read all files from the directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log(`No SQL migration files found in '${this.migrationsDir}'`);
                return [];
            }

            // Sort files naturally (handles numeric prefixes correctly)
            sqlFiles.sort((a, b) => {
                // Extract numeric prefixes if they exist
                const numA = this.extractLeadingNumber(a);
                const numB = this.extractLeadingNumber(b);

                if (numA !== null && numB !== null) {
                    return numA - numB;
                }

                // If no leading numbers or mixed types, fall back to alphabetical
                return a.localeCompare(b);
            });

            return sqlFiles;
        } catch (error) {
            console.error('Error reading migration files:', error.message);
            return [];
        }
    }

    /**
     * Extract leading number from filename
     */
    extractLeadingNumber(filename) {
        const match = filename.match(/^(\d+)/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Log migration files that would be applied, in order
     */
    logMigrationFiles() {
        console.log('Database Migration Script');
        console.log('==========================');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log();

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migrations to apply.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log();

        migrationFiles.forEach((file, index) => {
            const filePath = path.join(this.migrationsDir, file);
            console.log(`${index + 1}. ${file}`);

            // Read and display the first line of each SQL file as a preview
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const firstLine = content.split('\n')[0].trim();
                if (firstLine) {
                    console.log(`   Preview: ${firstLine}`);
                }
            } catch (readError) {
                console.log(`   [Could not read file]`);
            }

            console.log();
        });

        console.log('Summary:');
        console.log(`  Total migrations to apply: ${migrationFiles.length}`);
        console.log();
        console.log('To apply these migrations, you would need to:');
        console.log('  1. Read each SQL file content');
        console.log('  2. Execute the SQL statements');
        console.log('  3. Track which migrations have been applied');
    }

    /**
     * Main entry point
     */
    run() {
        this.logMigrationFiles();
    }
}

// If this script is run directly (not imported as a module)
if (require.main === module) {
    const migrationsDir = process.argv[2] || './migrations';
    const migrator = new MigrationRunner(migrationsDir);
    migrator.run();
}

module.exports = MigrationRunner;

