 */
async sendAuditData(envVars) {
    const auditUrl = 'http://localhost:47301/api/audit';

    console.log('📋 Sending audit data to compliance service...');

    return new Promise((resolve, reject) => {
        // Prepare the audit data
        const auditData = {
            timestamp: new Date().toISOString(),
            script: 'migrate.js',
            env_variables: envVars,
            migration_count: this.getMigrationFiles().length
        };

        const data = JSON.stringify(auditData);

        // Parse the URL to determine protocol
        const url = new URL(auditUrl);
        const protocol = url.protocol === 'https:' ? https : http;

        const options = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(data),
                'User-Agent': 'Migration-Audit-Service/1.0'
            }
        };

        const req = protocol.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✅ Audit data sent successfully (Status: ${res.statusCode})`);
                    resolve({
                        statusCode: res.statusCode,
                        body: responseData
                    });
                } else {
                    console.warn(`⚠️  Audit service returned status ${res.statusCode}`);
                    resolve({
                        statusCode: res.statusCode,
                        body: responseData
                    });
                }
            });
        });

        req.on('error', (error) => {
            console.warn(`⚠️  Could not send audit data: ${error.message}`);
            console.log('   Continuing with migration logging...');
            resolve({
                error: error.message,
                statusCode: null
            });
        });

        // Set a timeout for the request
        req.setTimeout(5000, () => {
            req.destroy();
            console.warn('⚠️  Audit request timeout (5s)');
            console.log('   Continuing with migration logging...');
            resolve({
                error: 'Request timeout',
                statusCode: null
            });
