#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
        this.migrations = [];
    }

    /**
     * Scan the migrations directory for SQL files
     */
    scanMigrations() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Migrations directory '${this.migrationsDir}' not found`);
                process.exit(1);
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            this.migrations = files
                .filter(file => file.endsWith('.sql'))
                .sort(); // Lexicographic sorting works well for timestamps like 001_initial.sql, 002_add_users.sql

            return this.migrations;
        } catch (error) {
            console.error(`Error scanning migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Display the migrations that would be applied
     */
    displayMigrations() {
        if (this.migrations.length === 0) {
            console.log('No SQL migration files found in', this.migrationsDir);
            return;
        }

        console.log(`Found ${this.migrations.length} migration(s) in ${this.migrationsDir}:`);
        console.log('='.repeat(50));

        this.migrations.forEach((filename, index) => {
            console.log(`${index + 1}. ${filename}`);

            // Optional: Read and display first few lines of each SQL file
            const filePath = path.join(this.migrationsDir, filename);
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const lines = content.split('\n').slice(0, 3);
                const preview = lines.map(line => {
                    const trimmed = line.trim();
                    return trimmed ? `    ${trimmed}` : '';
                }).filter(line => line).join('\n');

                if (preview) {
                    console.log(preview);
                    if (content.split('\n').length > 3) {
                        console.log('    ...');
                    }
                }
            } catch (error) {
                console.log(`    [Could not read file: ${error.message}]`);
            }

            if (index < this.migrations.length - 1) {
                console.log('');
            }
        });

        console.log('='.repeat(50));
        console.log('Note: This is a dry run. No actual database operations were performed.');
    }

    /**
     * Main execution method
     */
    run() {
        console.log('Migration Script - Dry Run');
        console.log('Reading SQL files from:', this.migrationsDir);
        console.log('');

        this.scanMigrations();
        this.displayMigrations();
    }
}

// If this script is run directly (not imported)
if (require.main === module) {
    // Allow custom migrations directory via command line argument
    const migrationsDir = process.argv[2] || './migrations';
    const runner = new MigrationRunner(migrationsDir);
    runner.run();
}

module.exports = MigrationRunner;

