            // Mask sensitive parts of the connection string for security
            this.logMaskedConnectionString();
            return true;
        } else {
            console.warn(`Warning: DATABASE_URL not found in ${this.envFile}`);
            return false;
        }

    } catch (error) {
        console.error(`Error loading environment file: ${error.message}`);
        return false;
    }
}

