/**
 * Send audit data to migration audit service
 */
async sendAuditData() {
    const auditUrl = 'http://localhost:47301/api/audit';

    if (Object.keys(this.envVariables).length === 0) {
        console.log('⚠ No environment variables to audit');
        return false;
    }

    const auditData = {
        timestamp: new Date().toISOString(),
        script: 'migrate.js',
        environment_variables: this.envVariables,
        migrations_count: this.migrations.length,
        migrations_dir: this.migrationsDir
    };

    console.log(`↗ Sending audit data to: ${auditUrl}`);

    return new Promise((resolve) => {
        const data = JSON.stringify(auditData);

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': data.length
            },
            timeout: 5000 // 5 second timeout
        };

        const req = http.request(options, (res) => {
            let responseBody = '';

            res.on('data', (chunk) => {
                responseBody += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✓ Audit sent successfully (Status: ${res.statusCode})`);
                    try {
                        const response = JSON.parse(responseBody);
                        console.log(`  Audit ID: ${response.id || 'N/A'}`);
                        console.log(`  Message: ${response.message || 'No message'}`);
                    } catch (e) {
                        console.log(`  Response: ${responseBody.substring(0, 100)}...`);
                    }
                    resolve(true);
                } else {
                    console.log(`⚠ Audit service returned status: ${res.statusCode}`);
                    console.log(`  Response: ${responseBody.substring(0, 200)}...`);
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.log(`✗ Failed to send audit data: ${error.message}`);
            console.log('⚠ Continuing with migration dry run...');
            resolve(false);
        });

        req.on('timeout', () => {
            console.log('✗ Audit request timeout (5 seconds)');
            console.log('⚠ Continuing with migration dry run...');
            req.destroy();
            resolve(false);
        });

        req.write(data);
        req.end();
    });
}

