            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✓ Audit sent successfully (Status: ${res.statusCode})`);
                    resolve(true);
                } else {
                    console.log(`⚠ Audit service returned status: ${res.statusCode}`);
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.log(`✗ Failed to send audit data: ${error.message}`);
            console.log('⚠ Continuing with migration dry run...');
            resolve(false);
        });

        req.on('timeout', () => {
