#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
                console.log('Creating migrations directory...');
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                console.log('Migrations directory created. No migration files to apply.');
                return [];
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort(); // Natural sort will work for numbered files

            return sqlFiles.map(file => ({
                name: file,
                path: path.join(this.migrationsDir, file)
            }));

        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Log migration files in order they would be applied
     */
    logMigrations() {
        console.log('=== Database Migration Script ===');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log('='.repeat(50));

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found to apply.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

        // Log each migration file in order
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);

            // Optionally read and show a preview of the SQL content
            try {
                const content = fs.readFileSync(file.path, 'utf8');
                const preview = content.split('\n')[0].substring(0, 60);
                console.log(`   Preview: ${preview}${preview.length >= 60 ? '...' : ''}`);
            } catch (error) {
                console.log(`   Error reading file: ${error.message}`);
            }

            console.log(); // Empty line for readability
        });

        console.log('='.repeat(50));
        console.log('Summary:');
        console.log(`• Total migrations to apply: ${migrationFiles.length}`);
        console.log('• This is a dry-run. No actual database changes were made.');
        console.log('• To apply migrations, you would need to execute the SQL files.');
        console.log('='.repeat(50));
    }

    /**
     * Alternative method with more detailed information
     */
    listMigrationsDetailed() {
        console.log('\n=== Detailed Migration Information ===');

        const migrationFiles = this.getMigrationFiles();

        migrationFiles.forEach((file, index) => {
            try {
                const stats = fs.statSync(file.path);
                const content = fs.readFileSync(file.path, 'utf8');
                const lines = content.split('\n').length;
                const size = stats.size;

                console.log(`\nMigration #${index + 1}: ${file.name}`);
                console.log(`  Path: ${file.relativePath || file.path}`);
                console.log(`  Size: ${size} bytes`);
                console.log(`  Lines: ${lines}`);
                console.log(`  First line: ${content.split('\n')[0].substring(0, 50)}...`);
            } catch (error) {
                console.log(`\nMigration #${index + 1}: ${file.name}`);
                console.log(`  Error: Could not read file details`);
            }
        });
    }
}

/**
 * Main execution
 */
function main() {
    const migrationScript = new MigrationScript();

    // Parse command line arguments
    const args = process.argv.slice(2);
    const detailed = args.includes('--detailed') || args.includes('-d');

    if (args.includes('--help') || args.includes('-h')) {
        console.log(`
Usage: node migrate.js [options]

Options:
  -h, --help     Show this help message
  -d, --detailed Show detailed migration information
  --dry-run      Default behavior - show what would be applied

Examples:
  node migrate.js          # Show migrations in order
  node migrate.js --detailed  # Show detailed information
  node migrate.js --help   # Show this help
        `);
        return;
    }

    migrationScript.logMigrations();

    if (detailed) {
        migrationScript.listMigrationsDetailed();
    }
}

// Run the script if this file is executed directly
if (require.main === module) {
    main();
}

// Export for testing or programmatic use
module.exports = MigrationScript;

