#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Reads DATABASE_URL from .env.test and logs connection message.
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.envFilePath = path.join(__dirname, '.env.test');
        this.databaseUrl = null;
    }

    /**
     * Read DATABASE_URL from .env.test file
     * @returns {string|null} The DATABASE_URL or null if not found
     */
    readDatabaseUrl() {
        try {
            if (!fs.existsSync(this.envFilePath)) {
                console.warn(`Warning: Environment file not found at ${this.envFilePath}`);
                return null;
            }

            const envContent = fs.readFileSync(this.envFilePath, 'utf8');
            const lines = envContent.split('\n');

            for (const line of lines) {
                if (line.startsWith('DATABASE_URL=')) {
                    return line.substring('DATABASE_URL='.length).trim();
                }
            }

            console.warn('Warning: DATABASE_URL not found in .env.test');
            return null;

        } catch (error) {
            console.warn(`Warning: Could not read .env.test: ${error.message}`);
            return null;
        }
    }

    /**
     * Log database connection information
     */
    logDatabaseConnection() {
        this.databaseUrl = this.readDatabaseUrl();

        if (this.databaseUrl) {
            // For security, don't log the full URL with credentials
            const urlParts = this.databaseUrl.split('://');
            const protocol = urlParts[0];
            const rest = urlParts[1] || '';

            // Extract host and database name
            const hostMatch = rest.match(/@([^/]+)/);
            const dbMatch = rest.match(/\/([^?]+)/);

            const host = hostMatch ? hostMatch[1] : 'unknown';
            const dbName = dbMatch ? dbMatch[1] : 'unknown';

