                console.log('  Database type: PostgreSQL');
            } else if (protocol === 'mysql') {
                console.log('  Database type: MySQL');
            } else if (protocol === 'mongodb') {
                console.log('  Database type: MongoDB');
            } else {
                console.log(`  Database type: ${protocol}`);
            }
        } else {
            console.log('⚠ No database connection configured');
            console.log('  Note: Using .env.test for configuration');
        }

        console.log(); // Empty line for readability
    }

    /**
     * Get all SQL migration files from the migrations directory
