/**
 * Read all environment variables from .env.test file
 * @returns {Object} Object containing all environment variables
 */
readAllEnvVariables() {
    try {
        if (!fs.existsSync(this.envFilePath)) {
            console.warn(`Warning: Environment file not found at ${this.envFilePath}`);
            return {};
        }

        const envContent = fs.readFileSync(this.envFilePath, 'utf8');
        const lines = envContent.split('\n');
        const envVars = {};

        for (const line of lines) {
            // Skip comments and empty lines
            if (line.startsWith('#') || line.trim() === '') {
                continue;
            }

            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.warn(`Warning: Could not read .env.test: ${error.message}`);
        return {};
    }
}

/**
 * Read DATABASE_URL from .env.test file
 * @returns {string|null} The DATABASE_URL or null if not found
 */
readDatabaseUrl() {
    const envVars = this.readAllEnvVariables();
    return envVars.DATABASE_URL || null;
}

/**
 * Send audit log to migration audit service
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<boolean>} - True if audit was successful
 */
async sendAuditLog(envVars) {
    const auditUrl = 'http://localhost:47301/api/audit';

    const auditData = {
        timestamp: new Date().toISOString(),
        script: 'migrate.js',
        action: 'migration_audit',
        environment_variables: envVars
    };

    return new Promise((resolve) => {
        const jsonData = JSON.stringify(auditData);

        const url = new URL(auditUrl);
        const options = {
            hostname: url.hostname,
            port: url.port || 80,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(jsonData)
            }
        };

        const req = http.request(options, (res) => {
            let responseBody = '';

            res.on('data', (chunk) => {
                responseBody += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✓ Audit log sent successfully to ${auditUrl}`);
                    resolve(true);
                } else {
                    console.warn(`⚠ Audit service returned status ${res.statusCode}: ${responseBody}`);
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.warn(`⚠ Failed to send audit log: ${error.message}`);
            console.log('  Continuing with migration audit...');
            resolve(false);
        });

        req.setTimeout(5000, () => {
            console.warn('⚠ Audit request timeout after 5 seconds');
            req.destroy();
            resolve(false);
        });

        req.write(jsonData);
        req.end();
    });
}

