    const dbMatch = rest.match(/\/([^?]+)/);

    const host = hostMatch ? hostMatch[1] : 'unknown';
    const dbName = dbMatch ? dbMatch[1] : 'unknown';

    console.log(`✓ Connected to database: ${protocol}://***@${host}/${dbName}`);
} else {
    console.log('⚠ No database connection configured');
}

console.log(); // Empty line for readability

// Check if migrations directory exists
if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory not found at ${migrationsDir}`);
    process.exit(1);
}

try {
    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in migrations directory.');
        process.exit(0);
    }

    // Sort files alphabetically (also works with numbered files like 001_name.sql)
    sqlFiles.sort();

    console.log('Migration files to apply (in order):');
    console.log('====================================');

    // Log each filename
    sqlFiles.forEach((filename, index) => {
        console.log(`${index + 1}. ${filename}`);
    });

    console.log('\nTotal files:', sqlFiles.length);
    console.log(`Environment variables audited: ${Object.keys(envVars).length}`);

} catch (error) {
    console.error(`Error reading migrations: ${error.message}`);
    process.exit(1);
}

