#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = migrationsDir;
  }

  /**
   * Get all migration files from the migrations directory
   * @returns {Array} Sorted array of migration file objects
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migration directory '${this.migrationsDir}' does not exist.`);
        process.exit(1);
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them
      const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => ({
          filename: file,
          filepath: path.join(this.migrationsDir, file),
          timestamp: this.extractTimestamp(file)
        }))
        .sort((a, b) => {
          // Sort by timestamp if available, otherwise by filename
          if (a.timestamp && b.timestamp) {
            return a.timestamp - b.timestamp;
          }
          return a.filename.localeCompare(b.filename);
        });

      return migrationFiles;
    } catch (error) {
      console.error(`Error reading migration directory: ${error.message}`);
      process.exit(1);
    }
  }

  /**
   * Extract timestamp from filename if it exists
   * @param {string} filename - The migration filename
   * @returns {number|null} The timestamp or null
   */
  extractTimestamp(filename) {
    // Try to extract numeric prefix from filename
    const match = filename.match(/^(\d+)_/);
    if (match) {
      return parseInt(match[1], 10);
    }
    return null;
  }

  /**
   * Read and return the SQL content of a migration file
   * @param {string} filepath - Path to the migration file
   * @returns {string} The SQL content
   */
  readMigrationContent(filepath) {
    try {
      return fs.readFileSync(filepath, 'utf8');
    } catch (error) {
      console.error(`Error reading migration file ${filepath}: ${error.message}`);
      return '';
    }
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('Starting migration process...\n');
    console.log(`Reading migrations from: ${path.resolve(this.migrationsDir)}\n`);

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    migrationFiles.forEach((migration, index) => {
      console.log(`${index + 1}. ${migration.filename}`);

      // Optional: Show a preview of the SQL content
      const content = this.readMigrationContent(migration.filepath);
      const preview = content.length > 100 
        ? content.substring(0, 100) + '...' 
        : content;

      if (preview.trim()) {
        console.log(`   Preview: ${preview}`);
      }
      console.log(); // Empty line for readability
    });

    console.log('Ready to apply migrations.');
    console.log('Note: This script only logs the files. Actual database connection would be implemented separately.');
  }

  /**
   * Main entry point
   */
  run() {
    this.logMigrations();
  }
}

// Create and run the migration runner
const runner = new MigrationRunner();
runner.run();

