/**
 * Read DATABASE_URL from .env.test file
 */
readDatabaseUrl() {
  try {
    // Check if .env.test file exists
    if (!fs.existsSync(this.envFile)) {
      console.error(`Error: Environment file '${this.envFile}' does not exist.`);
      process.exit(1);
    }

    // Read the file
    const envContent = fs.readFileSync(this.envFile, 'utf8');

    // Parse the file line by line
    const lines = envContent.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Try to parse KEY=VALUE format
      const match = trimmedLine.match(/^DATABASE_URL\s*=\s*(.+)$/);
      if (match) {
        this.databaseUrl = match[1].trim();
        break;
      }
    }

    if (!this.databaseUrl) {
      console.error(`Error: DATABASE_URL not found in ${this.envFile}`);
      process.exit(1);
    }

    console.log(`✓ Successfully read DATABASE_URL from ${this.envFile}`);

    // Attempt to parse and validate the connection string (without actually connecting)
    this.validateDatabaseUrl();

  } catch (error) {
    console.error(`Error reading ${this.envFile}: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Validate the database URL format
 */
validateDatabaseUrl() {
  try {
    // Basic validation of PostgreSQL URL format
    const urlPattern = /^postgres(?:ql)?:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = this.databaseUrl.match(urlPattern);

    if (match) {
      const [, username, , host, port, database] = match;
      console.log(`✓ Database connection URL parsed successfully:`);
      console.log(`  Host: ${host}:${port}`);
      console.log(`  Database: ${database}`);
      console.log(`  Username: ${username}`);
      console.log(`  (Password and sensitive details hidden for security)\n`);
    } else {
      console.log(`✓ Database URL found, but format may be non-standard`);
      console.log(`  URL: ${this.maskSensitiveInfo(this.databaseUrl)}\n`);
    }
  } catch (error) {
    console.log(`✓ Database URL found, but validation failed: ${error.message}\n`);
  }
}

/**
 * Mask sensitive information in the database URL for logging
 */
maskSensitiveInfo(url) {
  // Simple masking of password in connection string
  return url.replace(/:\/\/[^:]+:[^@]+@/, '://****:****@');
}

/**
 * Get all migration files from the migrations directory
 * @returns {Array} Sorted array of migration file objects
 */
getMigrationFiles() {
  try {
    // Check if migrations directory exists
