#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = './migrations';

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            process.exit(1);
        }

        // Read all files from the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = files.filter(file => file.toLowerCase().endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found.');
            return [];
        }

        // Sort files in natural order (by number prefix if present)
        sqlFiles.sort((a, b) => {
            // Extract numeric prefixes for ordering
            const numA = parseInt(a.match(/^(\d+)/)?.[0] || '0');
            const numB = parseInt(b.match(/^(\d+)/)?.[0] || '0');

            if (numA !== numB) {
                return numA - numB;
            }
            // If no numeric prefix or same number, sort alphabetically
            return a.localeCompare(b);
        });

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

function getMigrationContent(filename) {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    try {
        return fs.readFileSync(filePath, 'utf8');
    } catch (error) {
        console.error(`Error reading migration file '${filename}': ${error.message}`);
        return null;
    }
}

function logMigration(filename, content) {
    console.log(`\n📄 Migration: ${filename}`);
    console.log('─'.repeat(50));

    if (content) {
        const lines = content.split('\n');
        lines.forEach(line => {
            if (line.trim()) {
                console.log(`   ${line}`);
            }
        });
    } else {
        console.log('   (Could not read file content)');
    }
    console.log('─'.repeat(50));
}

function main() {
    console.log('🔍 Scanning for database migrations...');
    console.log(`📁 Directory: ${MIGRATIONS_DIR}`);
    console.log('='.repeat(60));

    const migrations = readMigrations();

    if (migrations.length === 0) {
        console.log('✅ No migrations to apply.');
        return;
    }

    console.log(`📊 Found ${migrations.length} migration file(s):`);
    console.log('='.repeat(60));

    // Log each migration in order
    migrations.forEach((filename, index) => {
        const content = getMigrationContent(filename);
        logMigration(filename, content);
    });

    console.log('\n📋 Summary:');
    console.log('='.repeat(60));
    console.log(`Total migrations found: ${migrations.length}`);
    console.log('\nMigration order would be:');
    migrations.forEach((filename, index) => {
        console.log(`  ${index + 1}. ${filename}`);
    });
    console.log('='.repeat(60));
    console.log('✅ Migration scan complete. No changes were made to the database.');
    console.log('💡 To actually apply these migrations, you would need to:');
    console.log('   1. Connect to your database');
    console.log('   2. Execute the SQL statements from each file');
    console.log('   3. Track which migrations have been applied');
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = { readMigrations, getMigrationContent };

