#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * It also reads DATABASE_URL from .env.test and logs a connection message.
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

function getDatabaseUrl() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_FILE)) {
            console.warn(`⚠️  Warning: Environment file '${ENV_FILE}' not found.`);
            return null;
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');

        // Parse DATABASE_URL from the file
        const lines = envContent.split('\n');
        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip comments and empty lines
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Look for DATABASE_URL
            if (trimmedLine.startsWith('DATABASE_URL=')) {
                // Extract everything after DATABASE_URL=
                const dbUrl = trimmedLine.substring('DATABASE_URL='.length).trim();

                // Remove quotes if present
                const cleanedUrl = dbUrl.replace(/^["']|["']$/g, '');

                return cleanedUrl;
            }
        }

        console.warn(`⚠️  Warning: DATABASE_URL not found in '${ENV_FILE}'.`);
        return null;
    } catch (error) {
        console.error(`❌ Error reading environment file '${ENV_FILE}': ${error.message}`);
        return null;
    }
}

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            process.exit(1);
        }

        // Read all files from the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = files.filter(file => file.toLowerCase().endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found.');
            return [];
        }

        // Sort files in migration order
        // Prioritize files with numeric prefixes, then alphabetical
        sqlFiles.sort((a, b) => {
            // Extract numeric prefixes (must be at the beginning followed by underscore)
            const numMatchA = a.match(/^(\d+)_/);
            const numMatchB = b.match(/^(\d+)_/);

            // Files with numeric prefixes come first
            if (numMatchA && !numMatchB) return -1;
            if (!numMatchA && numMatchB) return 1;

            // Both have numeric prefixes, sort numerically
            if (numMatchA && numMatchB) {
                const numA = parseInt(numMatchA[1]);
                const numB = parseInt(numMatchB[1]);
                return numA - numB;
            }

            // Neither has numeric prefix, sort alphabetically
            return a.localeCompare(b);
        });

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

function getMigrationContent(filename) {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    try {
        return fs.readFileSync(filePath, 'utf8');
    } catch (error) {
        console.error(`Error reading migration file '${filename}': ${error.message}`);
        return null;
    }
}

function logMigration(filename, content) {
    console.log(`\n📄 Migration: ${filename}`);
    console.log('─'.repeat(50));

    if (content) {
        const lines = content.split('\n');
        lines.forEach(line => {
            if (line.trim()) {
                console.log(`   ${line}`);
            }
        });
    } else {
        console.log('   (Could not read file content)');
    }
    console.log('─'.repeat(50));
}

function logConnectionInfo(databaseUrl) {
    console.log('🔌 Connection Information:');
    console.log('─'.repeat(40));

    if (databaseUrl) {
        console.log('✅ Successfully parsed DATABASE_URL from environment');

        // Parse and mask the URL for security
        try {
            // For PostgreSQL URLs: postgres://user:password@host:port/database
            const urlRegex = /^(postgres:\/\/)([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
            const match = databaseUrl.match(urlRegex);

            if (match) {
                const [, protocol, username, password, host, port, database] = match;
                console.log(`   Protocol: ${protocol.replace('://', '')}`);
                console.log(`   Username: ${username}`);
                console.log(`   Password: ${'*'.repeat(password.length)} (hidden)`);
                console.log(`   Host: ${host}`);
                console.log(`   Port: ${port}`);
                console.log(`   Database: ${database}`);
                console.log(`\n   🔗 Connection would be established to: ${protocol}${username}:***@${host}:${port}/${database}`);
            } else {
                // For other URL formats or if parsing fails, just show a masked version
                console.log(`   Database URL: ${maskDatabaseUrl(databaseUrl)}`);
            }
        } catch (error) {
            console.log(`   Database URL: ${maskDatabaseUrl(databaseUrl)}`);
        }
    } else {
        console.log('⚠️  No DATABASE_URL configured');
        console.log('   Connection will not be established');
    }
    console.log('─'.repeat(40));
}

function maskDatabaseUrl(url) {
    // Simple masking for security
    return url.replace(/:([^:@]+)@/, ':***@');
}

function main() {
    console.log('🚀 Starting Database Migration Script');
    console.log('='.repeat(60));

    // Read and log connection information
    const databaseUrl = getDatabaseUrl();
    logConnectionInfo(databaseUrl);

    console.log('\n🔍 Scanning for database migrations...');
    console.log(`📁 Directory: ${MIGRATIONS_DIR}`);
    console.log('='.repeat(60));

    const migrations = readMigrations();

    if (migrations.length === 0) {
        console.log('✅ No migrations to apply.');
        return;
    }

    console.log(`📊 Found ${migrations.length} migration file(s):`);
    console.log('='.repeat(60));

    // Log each migration in order
    migrations.forEach((filename, index) => {
        const content = getMigrationContent(filename);
        logMigration(filename, content);
    });

    console.log('\n📋 Summary:');
    console.log('='.repeat(60));
    console.log(`Total migrations found: ${migrations.length}`);
    console.log('\nMigration order would be:');
    migrations.forEach((filename, index) => {
        console.log(`  ${index + 1}. ${filename}`);
    });
    console.log('='.repeat(60));

    if (databaseUrl) {
        console.log('✅ Migration scan complete. Ready to apply migrations.');
        console.log('💡 To apply these migrations to the database:');
        console.log('   1. Connection is configured via DATABASE_URL in .env.test');
        console.log('   2. Execute the SQL statements from each file in order');
        console.log('   3. Track which migrations have been applied');
    } else {
        console.log('⚠️  Migration scan complete. No database connection configured.');
        console.log('💡 To apply these migrations, you would need to:');
        console.log('   1. Add DATABASE_URL to .env.test');
        console.log('   2. Connect to your database');
        console.log('   3. Execute the SQL statements from each file');
        console.log('   4. Track which migrations have been applied');
    }
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = { readMigrations, getMigrationContent };

