const path = require('path');

/**
 * Simple Database Migration Script
 * 
 * Reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = './migrations';

try {
  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Directory '${migrationsDir}' not found.`);
    console.error('Please create a migrations directory with SQL files.');
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in the migrations directory.');
    process.exit(0);
  }

  // Sort files by name (which should include numeric prefixes for ordering)
  const sortedFiles = sqlFiles.sort((a, b) => {
    // Try to extract numeric prefixes for sorting
    const numA = parseInt(a.match(/^(\d+)/)?.[1] || '999999');
    const numB = parseInt(b.match(/^(\d+)/)?.[1] || '999999');

    // Sort by numeric prefix first, then by filename
    if (numA !== numB) {
      return numA - numB;
    }
    return a.localeCompare(b);
