#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 * It also reads DATABASE_URL from .env.test and logs connection status.
 * Before running migrations, it sends all .env.test values to audit service.
 */

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.envFilePath = path.join(__dirname, '.env.test');
    this.auditUrl = 'http://localhost:47301/api/audit';
    this.migrationFiles = [];
    this.databaseUrl = null;
    this.envVariables = {};
  }

  /**
   * Read all environment variables from .env.test file
   * @returns {object} Object containing all env variables
   */
  readEnvVariables() {
    try {
      if (!fs.existsSync(this.envFilePath)) {
        console.warn(`Warning: Environment file '${this.envFilePath}' not found.`);
        return {};
      }

      const envContent = fs.readFileSync(this.envFilePath, 'utf8');
      const lines = envContent.split('\n');
      const variables = {};

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Parse key=value pairs
        const match = trimmedLine.match(/^([A-Za-z0-9_]+)\s*=\s*(.+)$/);
        if (match) {
          const key = match[1];
          const value = match[2].trim();
          variables[key] = value;
        }
      }

      return variables;
    } catch (error) {
      console.error(`Error reading environment file: ${error.message}`);
      return {};
    }
  }

  /**
   * Send audit data to compliance logging service
   * @param {object} auditData - The data to send
   * @returns {Promise<boolean>} Whether the audit was successful
   */
  async sendAuditData(auditData) {
    return new Promise((resolve) => {
      const postData = JSON.stringify({
        timestamp: new Date().toISOString(),
        script: 'migrate.js',
        action: 'migration_preview',
        ...auditData
      });

      const options = {
        hostname: 'localhost',
        port: 47301,
        path: '/api/audit',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData)
        },
        timeout: 5000 // 5 second timeout
      };

      console.log('Sending audit data to compliance logging service...');

      const req = http.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            try {
              const responseJson = JSON.parse(responseData);
              if (responseJson.status === 'ok' || responseJson.status === 'OK' || responseJson.status === 200) {
                console.log(`✓ Audit logged successfully`);
                resolve(true);
              } else {
                console.warn(`⚠ Audit service returned non-ok status: ${responseJson.status}`);
                resolve(false);
              }
            } catch (e) {
              console.log(`✓ Audit request completed`);
              resolve(true);
            }
          } else {
            console.warn(`⚠ Audit service returned status: ${res.statusCode}`);
            resolve(false);
          }
        });
      });

      req.on('error', (error) => {
        console.warn(`⚠ Could not reach audit service: ${error.message}`);
        console.warn('  Continuing with migrations...');
        resolve(false);
      });

      req.on('timeout', () => {
        console.warn('⚠ Audit service request timed out after 5 seconds');
        console.warn('  Continuing with migrations...');
        req.destroy();
        resolve(false);
      });

      req.write(postData);
      req.end();
    });
  }

  /**
   * Get all migration files in the migrations directory
   * @returns {Array} Sorted array of migration file objects
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory '${this.migrationsDir}' not found.`);
        process.exit(1);
      }

      // Read all files in the migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for .sql files and sort them numerically/alphabetically
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => ({
          filename: file,
          fullPath: path.join(this.migrationsDir, file),
          number: this.extractMigrationNumber(file)
        }))
        .sort((a, b) => {
          // Sort by migration number if available, otherwise by filename
          if (a.number !== null && b.number !== null) {
            return a.number - b.number;
          }
          return a.filename.localeCompare(b.filename);
        });

      return sqlFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      process.exit(1);
    }
  }

  /**
   * Extract migration number from filename (e.g., "001_...", "002_...")
   * @param {string} filename - The migration filename
   * @returns {number|null} The migration number or null if not found
   */
  extractMigrationNumber(filename) {
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : null;
  }

  /**
   * Read and return the content of a migration file
   * @param {string} filePath - Path to the migration file
   * @returns {string} The SQL content
   */
  readMigrationContent(filePath) {
    try {
      return fs.readFileSync(filePath, 'utf8').trim();
    } catch (error) {
      console.error(`Error reading migration file ${filePath}: ${error.message}`);
      return '';
    }
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('=== Migration Files ===');
    console.log(`Reading from: ${this.migrationsDir}`);
    console.log('='.repeat(50));

    this.migrationFiles = this.getMigrationFiles();

    if (this.migrationFiles.length === 0) {
      console.log('No migration files found in the migrations directory.');
      return;
    }

    console.log(`Found ${this.migrationFiles.length} migration file(s):\n`);

    this.migrationFiles.forEach((migration, index) => {
      console.log(`${index + 1}. ${migration.filename}`);

      // Optional: Show a preview of the SQL content
      const content = this.readMigrationContent(migration.fullPath);
      if (content) {
        const preview = content.length > 100 ? content.substring(0, 100) + '...' : content;
        console.log(`   SQL: ${preview}`);
      }

      console.log(); // Empty line for readability
    });

    console.log('='.repeat(50));
    console.log('Note: This is a dry-run. No actual database operations were performed.');
    console.log('To apply these migrations, you would need to execute the SQL statements.');
  }

  /**
   * Parse and validate database URL
   * @param {string} url - The database URL
   * @returns {object|null} Parsed database connection info or null if invalid
   */
  parseDatabaseUrl(url) {
    try {
      // Parse PostgreSQL URL format: postgres://username:password@host:port/database
      const urlPattern = /^(?:postgres(?:ql)?:\/\/)([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
      const match = url.match(urlPattern);

      if (!match) {
        console.warn('Warning: Database URL format is not standard PostgreSQL format.');
        return { url };
      }

      const [, username, password, host, port, database] = match;

      // Mask password for security when logging
      const maskedPassword = password.substring(0, 3) + '***' + password.substring(password.length - 3);
      const maskedUrl = url.replace(password, maskedPassword);

      return {
        url: maskedUrl,
        username,
        password: maskedPassword,
        host,
        port: parseInt(port, 10),
        database,
        originalUrl: url
      };
    } catch (error) {
      console.error(`Error parsing database URL: ${error.message}`);
      return { url };
    }
  }

  /**
   * Mask sensitive value for audit logging
   * @param {string} value - The value to mask
   * @returns {string} Masked value
   */
  maskSensitiveValue(value) {
    if (!value || value.length <= 6) {
      return '***';
    }
    return value.substring(0, 3) + '***' + value.substring(value.length - 3);
  }

  /**
   * Mask password in database URL
   * @param {string} dbUrl - The database URL
   * @returns {string} URL with masked password
   */
  maskDatabaseUrl(dbUrl) {
    try {
      const urlPattern = /^(postgres:\/\/[^:]+:)([^@]+)(@.+)$/;
      const match = dbUrl.match(urlPattern);
      if (match) {
        const [, prefix, password, suffix] = match;
        const maskedPassword = this.maskSensitiveValue(password);
        return prefix + maskedPassword + suffix;
      }
      return dbUrl;
    } catch (error) {
      return dbUrl;
    }
  }

  /**
   * Log database connection information
   */
  async logDatabaseConnection() {
    this.envVariables = this.readEnvVariables();
    this.databaseUrl = this.envVariables.DATABASE_URL || null;

    console.log('=== Database Migration Script ===');

    // Send audit data before showing any connection info
    if (Object.keys(this.envVariables).length > 0) {
      console.log('Compliance Audit:');
      console.log('='.repeat(50));

      // Create audit payload with masked sensitive data
      const auditPayload = { ...this.envVariables };

      // Mask sensitive values in audit data
      const sensitiveKeys = ['AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY', 'ANTHROPIC_API_KEY', 'LOGFIRE_TOKEN'];
      sensitiveKeys.forEach(key => {
        if (auditPayload[key]) {
          auditPayload[key] = this.maskSensitiveValue(auditPayload[key]);
        }
      });

      // Special handling for DATABASE_URL
      if (auditPayload.DATABASE_URL) {
        auditPayload.DATABASE_URL = this.maskDatabaseUrl(auditPayload.DATABASE_URL);
      }

      console.log(`Sending ${Object.keys(auditPayload).length} environment variables to audit service`);
      console.log(`Audit endpoint: ${this.auditUrl}`);

      const auditSuccess = await this.sendAuditData({
        env_variables: auditPayload,
        migration_count: this.getMigrationFiles().length,
        dry_run: true
      });

      if (!auditSuccess) {
        console.log('⚠ Audit logging failed, but continuing with migration preview...');
      }

      console.log('='.repeat(50));
      console.log(); // Empty line for readability
    } else {
      console.log('No environment variables found in .env.test');
      console.log('='.repeat(50));
      console.log();
    }

    // Now show database connection info
    console.log('Database Connection Information:');
    console.log('='.repeat(50));

    if (this.databaseUrl) {
      const connectionInfo = this.parseDatabaseUrl(this.databaseUrl);

      if (connectionInfo.username && connectionInfo.host) {
        console.log(`✓ Connected to database successfully! (simulated)`);
        console.log(`  URL: ${connectionInfo.url}`);
        console.log(`  Host: ${connectionInfo.host}:${connectionInfo.port}`);
        console.log(`  Database: ${connectionInfo.database}`);
        console.log(`  Username: ${connectionInfo.username}`);
      } else {
        console.log(`✓ Using database URL: ${connectionInfo.url}`);
        console.log(`  Note: Connection simulation only - no actual connection made`);
      }
    } else {
      console.log('⚠ No DATABASE_URL configured in .env.test');
      console.log('  Please add DATABASE_URL to .env.test to enable database operations');
      console.log('  Example: DATABASE_URL=postgres://user:password@localhost:5432/dbname');
    }

    console.log('='.repeat(50));
    console.log(); // Empty line for readability
  }

  /**
   * Main execution method
   */
  async run() {
    try {
      await this.logDatabaseConnection();
      this.logMigrations();
    } catch (error) {
      console.error(`Error during migration process: ${error.message}`);
      process.exit(1);
    }
  }
}

// If this script is run directly (not imported as a module)
if (require.main === module) {
  const migrator = new MigrationRunner();
  migrator.run();
}

// Export for use as a module
module.exports = MigrationRunner;

