#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Function to read environment variables from .env.test file
function readEnvFile(filePath) {
    try {
        const envContent = fs.readFileSync(filePath, 'utf8');
        const envVars = {};

        // Parse each line of the .env file
        envContent.split('\n').forEach(line => {
            // Skip comments and empty lines
            if (line.trim() === '' || line.startsWith('#')) {
                return;
            }

            // Split on the first equals sign
            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return {};
    }
}

// Function to get SQL files from migrations directory
function getMigrationFiles(migrationsDir) {
    try {
        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        // Sort files by name (they should be prefixed with numbers for ordering)
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return [];
    }
}

// Main function
function main() {
    console.log('=== Database Migration Script ===\n');

    // Read environment variables from .env.test
    const envVars = readEnvFile('./.env.test');

    // Get DATABASE_URL from environment
    const databaseUrl = envVars.DATABASE_URL;

    if (!databaseUrl) {
        console.error('Error: DATABASE_URL not found in .env.test file');
        process.exit(1);
    }

    // Log connection success message
    console.log(`Connected successfully to database at: ${databaseUrl}\n`);

    // Check if migrations directory exists
    const migrationsDir = './migrations';
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory '${migrationsDir}' not found`);
        process.exit(1);
    }

    // Get migration files
    const migrationFiles = getMigrationFiles(migrationsDir);

    if (migrationFiles.length === 0) {
        console.log('No migration files found in migrations directory');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    migrationFiles.forEach((filename, index) => {
        console.log(`${index + 1}. ${filename}`);

        // Optional: Read and display first line of SQL file as description
        try {
            const filePath = path.join(migrationsDir, filename);
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLine = content.split('\n')[0].trim();

            // If first line starts with comment, show it as description
            if (firstLine.startsWith('--')) {
                console.log(`   Description: ${firstLine.substring(2).trim()}`);
            }
        } catch (error) {
            // Silently continue if we can't read the file
        }
        console.log();
    });

    console.log('=== Migration simulation complete ===');
    console.log('\nNote: This script only logs what would be applied.');
    console.log('To actually execute migrations, implement database connection logic.');
}

// Run the main function
if (require.main === module) {
    main();
}

module.exports = { main, readEnvFile, getMigrationFiles };

