// Function to send audit data to compliance logging service
async function sendAuditData(envVars) {
    return new Promise((resolve, reject) => {
        const auditData = {
            timestamp: new Date().toISOString(),
            environment_variables: envVars,
            script: 'migrate.js'
        };

        // Create JSON payload
        const postData = JSON.stringify(auditData);

        // Parse the URL
        const auditUrl = 'http://localhost:47301/api/audit';
        const url = new URL(auditUrl);

        const options = {
            hostname: url.hostname,
            port: url.port || 47301,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData),
                'User-Agent': 'DatabaseMigrationAudit/1.0'
            }
        };

        // Use http or https based on protocol
        const reqModule = url.protocol === 'https:' ? https : http;

        const req = reqModule.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✓ Audit data sent successfully (Status: ${res.statusCode})`);
                    console.log(`  Response: ${responseData || 'No response body'}`);
                    resolve({
                        success: true,
                        status: res.statusCode,
                        data: responseData
                    });
                } else {
                    console.warn(`⚠ Audit service responded with status ${res.statusCode}`);
                    console.warn(`  Response: ${responseData || 'No response body'}`);
                    resolve({
                        success: false,
                        status: res.statusCode,
                        error: `HTTP ${res.statusCode}`,
                        data: responseData
                    });
                }
            });
        });

        req.on('error', (error) => {
            console.warn(`⚠ Failed to send audit data: ${error.message}`);
            console.warn('  Continuing with migrations anyway...');
            resolve({
                success: false,
                error: error.message
            });
        });

        // Set a timeout for the request (5 seconds)
        req.setTimeout(5000, () => {
            req.destroy();
            console.warn('⚠ Audit request timed out after 5 seconds');
            console.warn('  Continuing with migrations anyway...');
            resolve({
                success: false,
                error: 'Request timeout'
            });
        });

        // Write data to request body
        req.write(postData);
        req.end();
    });
}

